window.ANSWER_TERMS = {"alfa-helix":{"match":"alfa-helices|alfa-helixen|alfa-helixes|alfa-helix|alfa helices|alfa helix|alpha-helices|alpha-helixes|alpha-helix|alpha helices|alpha helix|α-helices|α-helix","title":"Alfa-helix","short":"De alfa-helix is een veelvoorkomende secundaire eiwitstructuur: een rechtsdraaiende spiraal die bij elkaar wordt gehouden door waterstofbruggen in de ruggengraat van het eiwit.","definition":"<p>De <strong>alfa-helix</strong> is een element van de <em>secundaire</em> eiwitstructuur: een rechtsdraaiende spiraal met ongeveer 3,6 aminozuren per winding. Hij wordt gestabiliseerd door waterstofbruggen tussen de C=O van aminozuur <em>n</em> en de N–H van aminozuur <em>n+4</em> — dus tussen de <em>ruggengraat</em>-atomen, niet tussen de zijketens.</p><p>De zijketens steken naar buiten: hydrofiel richting het water, hydrofoob naar de kern van het eiwit. <em>Proline</em> mist de N–H en knikt de keten — de klassieke “helix-breaker”; ook glycine destabiliseert. Voorbeelden: keratine, collageen (drie helices ineengedraaid) en de normale vorm van het prioneiwit PrP<sup>C</sup>.</p>","image_url":"","wiki_title":"Alpha helix"},"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"lysosoom":{"title":"Lysosoom","short":"Membraanblaasje vol verterende enzymen dat afvalstoffen en opgenomen materiaal afbreekt.","definition":"<p>Het <b>lysosoom</b> is een blaasje omgeven door één membraan, gevuld met hydrolytische enzymen die bij een lage pH (~4,5) macromoleculen afbreken. Het is de 'maag' van de cel.</p><p>Het verteert materiaal dat via endocytose of fagocytose is opgenomen en ruimt via autofagie versleten celonderdelen op.</p>","image_url":"","wiki_title":"Lysosome","match":"lysosoom|lysosomen"},"mitochondrion":{"title":"Mitochondrion","short":"De 'energiecentrale' van de cel; produceert ATP via de citroenzuurcyclus en oxidatieve fosforylering.","definition":"<p>Het <b>mitochondrion</b> heeft een dubbele membraan; de binnenste is sterk geplooid (cristae). Hier vinden de citroenzuurcyclus en de elektronentransportketen plaats.</p><p>Zo levert het mitochondrion het grootste deel van de ATP van de cel. Het bevat eigen DNA en kan zich delen.</p>","image_url":"","wiki_title":"Mitochondrion","match":"mitochondrion|mitochondriën|mitochondrien|mitochondria|mitochondrium"},"actine":{"title":"Actine","short":"Eiwit dat microfilamenten vormt; betrokken bij celvorm, celbeweging en spiercontractie.","definition":"<p><b>Actine</b> is een van de meest voorkomende eiwitten in de cel. Losse moleculen (G-actine) polymeriseren tot dunne draden (F-actine): de microfilamenten van het cytoskelet.</p><p>Actinefilamenten geven de cel vorm, maken beweging en deling mogelijk en vormen samen met myosine het contractiele apparaat van spiercellen.</p>","image_url":"","wiki_title":"Actin","match":"actine|actinefilamenten|actinefilament"},"myosine":{"title":"Myosine","short":"Motoreiwit dat langs actinefilamenten beweegt en zo spiercontractie en intracellulair transport aandrijft.","definition":"<p><b>Myosine</b> is een motoreiwit dat onder verbruik van ATP kracht levert door langs actinefilamenten te 'lopen'.</p><p>In spiercellen glijden myosine- en actinefilamenten langs elkaar, wat de spier doet samentrekken (het glijdende-filamentmodel).</p>","image_url":"","wiki_title":"Myosin","match":"myosine|myosinefilamenten|myosinefilament"},"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"glycolipide":{"title":"Glycolipide","short":"Lipide met een suikergroep aan de buitenkant van de celmembraan; betrokken bij herkenning en bescherming.","definition":"<p>Een <b>glycolipide</b> is een membraanlipide waaraan aan de buitenzijde een suikerketen hangt.</p><p>Samen met glycoproteïnen vormt het de glycocalyx, die een rol speelt bij celherkenning en bescherming van het celoppervlak.</p>","image_url":"","wiki_title":"Glycolipid","match":"glycolipide|glycolipiden"},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"proteoglycaan":{"title":"Proteoglycaan","short":"Eiwit met lange glycosaminoglycaan-ketens; waterbindend hoofdbestanddeel van de extracellulaire matrix.","definition":"<p>Een <b>proteoglycaan</b> bestaat uit een kerneiwit met glycosaminoglycaan-ketens (zoals chondroïtinesulfaat). Door hun negatieve lading trekken ze veel water aan.</p><p>Ze vormen een gel-achtige grondsubstantie in bindweefsel en kraakbeen die druk opvangt en waarin vezels zijn ingebed.</p>","image_url":"","wiki_title":"Proteoglycan","match":"proteoglycaan|proteoglycanen"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"glycolyse":{"title":"Glycolyse","short":"Afbraak van glucose tot pyruvaat in het cytoplasma, met een kleine netto-opbrengst aan ATP en NADH.","definition":"<p><b>Glycolyse</b> splitst in het cytoplasma één glucose in tien stappen tot twee moleculen pyruvaat.</p><p>Het levert netto 2 ATP en 2 NADH op en verloopt zonder zuurstof. Bij aanwezigheid van zuurstof gaat pyruvaat de citroenzuurcyclus in.</p>","image_url":"","wiki_title":"Glycolysis","match":"glycolyse"},"citroenzuurcyclus":{"title":"Citroenzuurcyclus","short":"Kringloop in het mitochondrion die acetyl-CoA volledig oxideert en NADH, FADH₂ en CO₂ oplevert.","definition":"<p>De <b>citroenzuurcyclus</b> (Krebscyclus) vindt plaats in de mitochondriale matrix. Acetyl-CoA gaat de cyclus in en wordt stapsgewijs geoxideerd.</p><p>Er ontstaan NADH en FADH₂ (die de elektronentransportketen voeden), wat GTP/ATP en CO₂ als afvalstof.</p>","image_url":"","wiki_title":"Citric acid cycle","match":"citroenzuurcyclus|krebscyclus"},"acetyl-coa":{"title":"Acetyl-CoA","short":"Centrale metaboliet die een acetylgroep de citroenzuurcyclus in brengt; knooppunt van suiker-, vet- en eiwitafbraak.","definition":"<p><b>Acetyl-CoA</b> ontstaat uit pyruvaat (uit glycolyse), vetzuren en sommige aminozuren.</p><p>Het draagt zijn acetylgroep de citroenzuurcyclus in en is zo het centrale knooppunt van het energiemetabolisme.</p>","image_url":"","wiki_title":"Acetyl-CoA","match":"acetyl-coa|acetyl coa"},"pyruvaat":{"title":"Pyruvaat","short":"Eindproduct van de glycolyse; gaat bij zuurstof over in acetyl-CoA, zonder zuurstof in lactaat.","definition":"<p><b>Pyruvaat</b> (pyrodruivenzuur) is het eindproduct van de glycolyse.</p><p>Met zuurstof wordt het in het mitochondrion omgezet tot acetyl-CoA voor de citroenzuurcyclus; zonder zuurstof wordt het via gisting lactaat.</p>","image_url":"","wiki_title":"Pyruvic acid","match":"pyruvaat|pyrodruivenzuur"},"nadh":{"title":"NADH","short":"Elektronendrager die de citroenzuurcyclus 'oplaadt' en zijn elektronen aan de elektronentransportketen levert.","definition":"<p><b>NADH</b> is de gereduceerde vorm van NAD⁺. Het ontstaat als tijdens glycolyse en citroenzuurcyclus elektronen worden opgenomen.</p><p>In het mitochondrion staat NADH die elektronen weer af aan de elektronentransportketen, wat ATP oplevert.</p>","image_url":"","wiki_title":"Nicotinamide adenine dinucleotide","match":"nadh"},"citraat":{"title":"Citraat","short":"Eerste product van de citroenzuurcyclus, gevormd uit acetyl-CoA en oxaalacetaat.","definition":"<p><b>Citraat</b> (citroenzuur) ontstaat wanneer acetyl-CoA in de citroenzuurcyclus aan oxaalacetaat wordt gekoppeld.</p><p>Het is de eerste stap van de cyclus; de naamgever citroenzuurcyclus verwijst ernaar.</p>","image_url":"","wiki_title":"Citric acid","match":"citraat"},"glycosylering":{"title":"Glycosylering","short":"Post-translationele toevoeging van suikerketens aan een eiwit, vooral in ER en Golgi.","definition":"<p><b>Glycosylering</b> is het aanhechten van suikerketens aan een eiwit (of lipide), voornamelijk in het endoplasmatisch reticulum en het Golgi-complex.</p><p>Het beïnvloedt vouwing, stabiliteit en herkenning; het levert glycoproteïnen en glycolipiden op.</p>","image_url":"","wiki_title":"Glycosylation","match":"glycosylering|glycosylatie"},"fosforylering":{"title":"Fosforylering","short":"Toevoeging van een fosfaatgroep aan een eiwit; een veelgebruikte aan/uit-schakelaar van eiwitactiviteit.","definition":"<p><b>Fosforylering</b> is het koppelen van een fosfaatgroep aan een eiwit door een kinase. Een fosfatase haalt hem er weer af.</p><p>Zo schakelen cellen eiwitten razendsnel aan of uit — de basis van veel signaaltransductie.</p>","image_url":"","wiki_title":"Phosphorylation","match":"fosforylering|fosforylatie"},"neutrofiele granulocyt":{"title":"Neutrofiele granulocyt","short":"Meest voorkomende witte bloedcel en eerste verdedigingslinie tegen bacteriën via fagocytose.","definition":"<p>De <b>neutrofiele granulocyt</b> is de talrijkste leukocyt, met een gelobde kern, en als eerste ter plaatse bij een bacteriële infectie.</p><p>Hij ruimt bacteriën op door fagocytose en enzymen; dode neutrofielen vormen samen met bacterieresten de pus.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofiele granulocyt|neutrofiele granulocyten"},"eosinofiele granulocyt":{"title":"Eosinofiele granulocyt","short":"Witte bloedcel met rood-kleurende korrels, actief bij afweer tegen parasieten en bij allergie.","definition":"<p>De <b>eosinofiele granulocyt</b> heeft korrels die met eosine roodroze aankleuren en meestal een tweelobbige kern.</p><p>Hij is betrokken bij de afweer tegen wormparasieten en bij allergische processen zoals astma en eczeem; het aantal is dan vaak verhoogd.</p>","image_url":"","wiki_title":"Eosinophil","match":"eosinofiele granulocyt|eosinofiele granulocyten"},"monocyt":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyt|monocyten"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"meerlagig plaveiselepitheel":{"title":"Meerlagig plaveiselepitheel","short":"Epitheel van meerdere lagen platte cellen; beschermt tegen mechanische belasting (o.a. de opperhuid).","definition":"<p><b>Meerlagig plaveiselepitheel</b> bestaat uit meerdere cellagen met bovenop platte (plaveisel)cellen.</p><p>Het is bestand tegen slijtage en komt voor waar veel mechanische belasting is: epidermis, mondholte, slokdarm. In de huid is het verhoornd.</p>","image_url":"","wiki_title":"Stratified squamous epithelium","match":"meerlagig plaveiselepitheel"},"overgangsepitheel":{"title":"Overgangsepitheel","short":"Rekbaar epitheel (urotheel) dat van vorm verandert bij vullen en legen, o.a. in de blaas.","definition":"<p><b>Overgangsepitheel</b> (urotheel) kan uitrekken en samentrekken: de cellen worden platter als het orgaan zich vult.</p><p>Het bekleedt de urinewegen, zoals de blaas, en is daar ook een waterdichte barrière.</p>","image_url":"","wiki_title":"Transitional epithelium","match":"overgangsepitheel"},"meerrijig epitheel":{"title":"Meerrijig epitheel","short":"Eenlagig epitheel waarvan de kernen op verschillende hoogtes liggen, waardoor het meerlagig lijkt.","definition":"<p><b>Meerrijig (pseudomeerlagig) epitheel</b> lijkt uit meerdere lagen te bestaan doordat de celkernen op verschillende hoogtes zitten, maar alle cellen raken de basaalmembraan.</p><p>Het komt vaak trilhaardragend voor in de luchtwegen.</p>","image_url":"","wiki_title":"Pseudostratified columnar epithelium","match":"meerrijig epitheel|meerrijïg epitheel"},"collageen":{"title":"Collageen","short":"Sterkste structuureiwit van het lichaam; hoofdbestanddeel van bindweefsel, dermis, pezen en bot.","definition":"<p><b>Collageen</b> is het meest voorkomende eiwit in het lichaam en vormt sterke, drievoudig gewonden vezels.</p><p>In de dermis geeft het de huid trekvastheid; fibroblasten maken het aan. Voor de aanmaak is vitamine C nodig (hydroxylering van proline).</p>","image_url":"","wiki_title":"Collagen","match":"collageen"},"elastine":{"title":"Elastine","short":"Rekbaar bindweefseleiwit dat huid, longen en bloedvaten na uitrekking hun vorm laat hervinden.","definition":"<p><b>Elastine</b> vormt elastische vezels die kunnen uitrekken en daarna weer terugveren.</p><p>Het geeft de huid, longen en slagaderwanden hun elasticiteit. Afname van elastine draagt bij aan huidveroudering en rimpels.</p>","image_url":"","wiki_title":"Elastin","match":"elastine"},"macula":{"title":"Macula","short":"Vlakke, niet-voelbare huidverandering die alleen in kleur verschilt (een 'vlek').","definition":"<p>Een <b>macula</b> is een plat, met de vinger niet-voelbaar plekje dat zich alleen door kleur onderscheidt van de omgeving.</p><p>Voorbeelden zijn een sproet of een café-au-lait-vlek. Wordt hij groter dan ~1 cm, dan spreekt men van een patch.</p>","image_url":"","wiki_title":"Skin condition","match":"macula|maculae"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"pneumonie":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"pneumonie|longontsteking","option_only":true},"herpes zoster":{"title":"Herpes zoster (gordelroos)","short":"Herpes zoster is de reactivatie van het varicella-zostervirus uit een sensibel ganglion, met pijnlijke blaasjes in één dermatoom.","definition":"<p>Na waterpokken blijft het <strong>varicella-zostervirus</strong> latent aanwezig in sensibele ganglia (spinale ganglia of hersenzenuwganglia). Bij afnemende cellulaire afweer (ouderdom, immuunsuppressie) kan het reactiveren.</p><p>Dan ontstaan pijnlijke, gegroepeerde blaasjes op een rode ondergrond in één <em>dermatoom</em>, meestal eenzijdig. Complicaties zijn postherpetische neuralgie en, bij de n. ophthalmicus, oogbetrokkenheid (zoster ophthalmicus).</p>","image_url":"","wiki_title":"Shingles","match":"herpes zoster|gordelroos|zoster","option_only":true},"hydrochloorthiazide":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"hydrochloorthiazide|hctz|thiazide|thiazidediureticum|thiazide diureticum|hydrochloortiazide","option_only":true},"vitamine b1":{"title":"Vitamine B1 (thiamine)","short":"Thiamine is een cofactor voor o.a. pyruvaatdehydrogenase; tekort (vaak bij alcoholisme) geeft beriberi en Wernicke-encefalopathie.","definition":"<p><strong>Thiamine</strong> (vitamine B1) is als thiaminepyrofosfaat cofactor van enzymen in het koolhydraatmetabolisme, zoals <em>pyruvaatdehydrogenase</em>, α-ketoglutaraatdehydrogenase en transketolase.</p><p>Tekort komt vooral voor bij alcoholmisbruik en ondervoeding. Het geeft <em>beriberi</em> (neuropathie, hartfalen) en de <em>Wernicke-encefalopathie</em> (verwardheid, ataxie, oogbewegingsstoornissen), eventueel gevolgd door het syndroom van Korsakov. Geef thiamine vóór glucose bij een risicopatiënt.</p>","image_url":"","wiki_title":"Thiamine","match":"vitamine b1|thiamine|thiamine (vitamine b1)","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"roken":{"title":"Roken","short":"Roken is de belangrijkste vermijdbare oorzaak van ziekte en sterfte: het veroorzaakt o.a. longkanker, COPD en hart- en vaatziekten.","definition":"<p>Tabaksrook bevat nicotine (verslavend), koolmonoxide, teer en tientallen kankerverwekkende stoffen. <strong>Roken</strong> beschadigt het luchtwegepitheel en het endotheel en bevordert ontsteking en trombose.</p><p>Het is een hoofdoorzaak van longkanker en andere kankers (o.a. mond, slokdarm, blaas), COPD, atherosclerose (myocardinfarct, CVA, perifeer arterieel vaatlijden) en complicaties in de zwangerschap. Stoppen loont op elke leeftijd.</p>","image_url":"","wiki_title":"Tobacco smoking","match":"roken|tabaksgebruik|tabak","option_only":true},"vena cava superior":{"title":"Vena cava superior","short":"De vena cava superior voert het bloed van hoofd, hals, armen en thoraxwand terug naar het rechteratrium.","definition":"<p>De <strong>vena cava superior</strong> ontstaat door samenvloeiing van de linker en rechter v. brachiocephalica, achter het sternum rechts, en mondt uit in het <em>rechteratrium</em>.</p><p>Zij draineert hoofd, hals, armen en (via de v. azygos) de thoraxwand. Compressie door een tumor (vaak longcarcinoom of lymfoom) geeft het vena cava superior-syndroom: zwelling van gezicht en armen en gestuwde halsvenen.</p>","image_url":"","wiki_title":"Superior vena cava","match":"vena cava superior|v. cava superior|bovenste holle ader","option_only":true},"ductus thoracicus":{"title":"Ductus thoracicus","short":"De ductus thoracicus is het grootste lymfevat; hij voert de lymfe van het grootste deel van het lichaam af naar de linker veneuze hoek.","definition":"<p>De <strong>ductus thoracicus</strong> begint in de buik bij de cisterna chyli, loopt door de hiatus aorticus van het diafragma omhoog door het achterste mediastinum en mondt uit in de <em>linker veneuze hoek</em> (samenkomst v. jugularis interna en v. subclavia sinistra).</p><p>Hij draineert de lymfe van de benen, de buik (inclusief chylus met vetten uit de darm), de linker thoraxhelft, de linker arm en de linker kant van hoofd en hals. De rechter bovenkwadrant draineert via de ductus lymphaticus dexter.</p>","image_url":"","wiki_title":"Thoracic duct","match":"ductus thoracicus|borstbuis","option_only":true},"trachea":{"title":"Trachea","short":"De trachea is de luchtpijp van het strottenhoofd tot de splitsing (carina), verstevigd door C-vormige kraakbeenringen en bekleed met trilhaarepitheel.","definition":"<p>De <strong>trachea</strong> loopt van de onderrand van het cricoïd (±C6) tot de <em>carina</em> (±T4–T5), waar hij splitst in de linker en rechter hoofdbronchus.</p><p>Ze wordt opengehouden door 16–20 C-vormige ringen van hyalien kraakbeen die dorsaal open zijn; daar ligt de m. trachealis (gladde spier), tegen de slokdarm aan. De binnenkant is bekleed met <em>meerrijig trilhaarcilindrisch epitheel</em> met slijmbekercellen (respiratoir epitheel).</p>","image_url":"","wiki_title":"Trachea","match":"trachea|luchtpijp","option_only":true},"pneumothorax":{"title":"Pneumothorax","short":"Een pneumothorax is lucht in de pleuraholte, waardoor de long (deels) inklapt; acuut kortademig met pijn, bij spanningspneumothorax levensbedreigend.","definition":"<p>Bij een <strong>pneumothorax</strong> komt lucht tussen de pleurabladen, waardoor de negatieve intrapleurale druk verdwijnt en de long door zijn elastische terugslag inklapt.</p><p>Hij kan spontaan ontstaan (primair bij lange, slanke jonge mannen door blebs; secundair bij longziekte zoals COPD) of na trauma. Klachten: plotselinge pijn op de borst en kortademigheid; verminderd ademgeruis en hypersonore percussie. Bij een <em>spanningspneumothorax</em> hoopt lucht zich op als een ventiel, met verschuiving van het mediastinum en circulatoire shock: direct ontlasten.</p>","image_url":"","wiki_title":"Pneumothorax","match":"pneumothorax|klaplong","option_only":true},"x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"x-thorax|thoraxfoto|röntgenfoto van de thorax|x thorax|x-thorax (röntgenfoto)","option_only":true},"hypothalamus":{"title":"Hypothalamus","short":"De hypothalamus is het regelcentrum van de homeostase: hij stuurt hypofyse, autonoom zenuwstelsel, temperatuur, honger, dorst en circadiaan ritme.","definition":"<p>De <strong>hypothalamus</strong> is een klein deel van het diencephalon, onder de thalamus en rond de derde ventrikel. Hij is via het infundibulum verbonden met de hypofyse.</p><p>Hij maakt releasing- en inhibiting-hormonen (o.a. TRH, CRH, GnRH, GHRH, dopamine) die via het portale systeem de voorkwab sturen, en ADH en oxytocine die in de achterkwab worden afgegeven. Daarnaast regelt hij lichaamstemperatuur, honger en verzadiging, dorst, het slaap-waakritme (nucleus suprachiasmaticus) en het autonome zenuwstelsel.</p>","image_url":"","wiki_title":"Hypothalamus","match":"hypothalamus","option_only":true},"endotheelcellen":{"title":"Endotheelcellen","short":"Endotheelcellen bekleden als één dunne laag de binnenkant van alle bloed- en lymfevaten en regelen vaattonus, stolling en doorlaatbaarheid.","definition":"<p><strong>Endotheel</strong> is een enkellaags plaveiselepitheel dat de binnenwand (tunica intima) van bloed- en lymfevaten en het hart bekleedt.</p><p>Endotheelcellen zijn actief: ze maken vaatverwijders (NO, prostacycline) en -vernauwers (endotheline), houden het bloed vloeibaar (antistollingsfactoren) maar kunnen bij beschadiging de stolling activeren (von Willebrandfactor), en laten leukocyten via adhesiemoleculen het weefsel in tijdens ontsteking.</p>","image_url":"","wiki_title":"Endothelium","match":"endotheelcellen|endotheel|endotheelcel","option_only":true},"losmazig bindweefsel":{"title":"Losmazig bindweefsel","short":"Losmazig bindweefsel is los georganiseerd bindweefsel met veel grondsubstantie, cellen en weinig vezels; het vult ruimtes en draagt vaten en zenuwen.","definition":"<p><strong>Losmazig bindweefsel</strong> bevat relatief veel grondsubstantie en cellen (fibroblasten, macrofagen, mestcellen, leukocyten) en een los netwerk van collagene en elastische vezels.</p><p>Het ligt onder epitheel (bijv. lamina propria van slijmvliezen, papillaire dermis), rond bloedvaten en zenuwen en tussen organen. Het is flexibel, goed doorbloed en een belangrijke plaats voor afweer en oedeemvorming. Ter vergelijking: straf bindweefsel (pezen, banden) bestaat vooral uit dicht opeengepakte collagene vezels.</p>","image_url":"","wiki_title":"Loose connective tissue","match":"losmazig bindweefsel|los bindweefsel|areolair bindweefsel","option_only":true},"meerlagig kubisch epitheel":{"title":"Meerlagig kubisch epitheel","short":"Meerlagig kubisch epitheel bestaat uit twee of meer lagen kubusvormige cellen en komt vooral voor in de afvoergangen van klieren.","definition":"<p><strong>Meerlagig kubisch epitheel</strong> is zeldzaam in het lichaam. Meestal bestaat het uit twee lagen kubische cellen.</p><p>Het bekleedt vooral de grotere <em>afvoergangen van exocriene klieren</em>, zoals die van zweetklieren, speekselklieren en de borstklier, waar het een beschermende functie heeft.</p>","image_url":"","wiki_title":"Stratified cuboidal epithelium","match":"meerlagig kubisch epitheel|meerlagig kubusvormig epitheel","option_only":true},"mucosa":{"title":"Mucosa (slijmvlies)","short":"De mucosa is het slijmvlies: de binnenste laag van holle organen, bestaande uit epitheel, lamina propria en (in de darm) een laagje spier.","definition":"<p>De <strong>mucosa</strong> bekleedt de binnenkant van holle organen die met de buitenwereld in contact staan, zoals het maag-darmkanaal, de luchtwegen en de urinewegen.</p><p>Ze bestaat uit een <em>epitheel</em> (aangepast aan de functie: bijv. meerlagig plaveisel in de slokdarm, enkellaags cilindrisch in de darm), een <em>lamina propria</em> van losmazig bindweefsel met vaten en afweercellen en, in het maag-darmkanaal, een dun spierlaagje (muscularis mucosae).</p>","image_url":"","wiki_title":"Mucous membrane","match":"mucosa|slijmvlies|tunica mucosa","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarct|hartinfarct|acuut myocardinfarct|ami","option_only":true},"ventriculaire vullingsfase":{"title":"Ventriculaire vullingsfase","short":"De vullingsfase is het deel van de diastole waarin de AV-kleppen open zijn en bloed vanuit de atria de ventrikels instroomt.","definition":"<p>Tijdens de <strong>ventriculaire vullingsfase</strong> is de druk in de ventrikel lager dan in het atrium; de mitralis- en tricuspidalisklep staan open en de aorta- en pulmonalisklep zijn dicht.</p><p>De vulling verloopt in drie stappen: snelle passieve vulling direct na opening van de AV-kleppen, daarna langzame vulling (diastase), en ten slotte de <em>atriale contractie</em>, die vooral bij een hoge hartfrequentie of stijve ventrikel een belangrijk deel bijdraagt.</p>","image_url":"","wiki_title":"Cardiac cycle","match":"ventriculaire vullingsfase|vullingsfase|ventrikelvulling|diastolische vulling","option_only":true},"isovolumetrische relaxatiefase":{"title":"Isovolumetrische relaxatiefase","short":"In de isovolumetrische relaxatie ontspant de ventrikel terwijl alle kleppen gesloten zijn: de druk daalt snel, het volume blijft gelijk.","definition":"<p>De <strong>isovolumetrische relaxatiefase</strong> is het begin van de diastole. Het myocard ontspant terwijl zowel de semilunaire kleppen als de AV-kleppen gesloten zijn, zodat de ventrikeldruk snel daalt bij een gelijkblijvend volume (het eindsystolisch volume). Zodra de ventrikeldruk onder de atriumdruk zakt, openen de AV-kleppen en begint de vulling.</p>","image_url":"","wiki_title":"Cardiac cycle","match":"isovolumetrische relaxatiefase|isovolumetrische relaxatie|isovolumische relaxatie","option_only":true},"ejectiefase":{"title":"Ejectiefase","short":"In de ejectiefase is de ventrikeldruk hoger dan de druk in aorta/a. pulmonalis: de semilunaire kleppen staan open en het slagvolume wordt uitgepompt.","definition":"<p>De <strong>ejectiefase</strong> volgt op de isovolumetrische contractie. Zodra de druk in de linkerventrikel hoger wordt dan in de aorta (en rechts dan in de a. pulmonalis), openen de semilunaire kleppen en wordt bloed uitgedreven.</p><p>Eerst gaat dat snel, daarna langzamer. Tijdens deze fase daalt het ventrikelvolume van het einddiastolisch naar het eindsystolisch volume; het verschil is het slagvolume. De fase eindigt met het sluiten van de semilunaire kleppen (tweede harttoon).</p>","image_url":"","wiki_title":"Cardiac cycle","match":"ejectiefase|ejectie|uitdrijvingsfase|ventriculaire ejectie","option_only":true},"verzamelbuizen":{"title":"Verzamelbuis","short":"De verzamelbuis is het laatste deel van het nefron; hier wordt onder invloed van ADH water en van aldosteron natrium (met kaliumuitscheiding) teruggeresorbeerd.","definition":"<p>De <strong>verzamelbuizen</strong> verzamelen de voorurine van meerdere nefronen en lopen van de cortex door het merg naar de nierpapil. Het corticale deel heet de corticale verzamelbuis.</p><p>Er zijn twee belangrijke celtypen: <em>hoofdcellen</em>, die onder invloed van aldosteron natrium opnemen (ENaC) en kalium uitscheiden, en onder invloed van ADH aquaporine-2 inbouwen voor wateropname; en <em>schaltcellen</em>, die H⁺ of HCO₃⁻ uitscheiden voor het zuur-base-evenwicht. Hier wordt bepaald hoe geconcentreerd de urine uiteindelijk is.</p>","image_url":"","wiki_title":"Collecting duct system","match":"verzamelbuizen|verzamelbuis|corticale verzamelbuis|ductus colligens|tubulus colligens","option_only":true},"opstijgende been van de lis van henle":{"title":"Opstijgende been van de lis van Henle","short":"Het opstijgende been van de lis van Henle is ondoorlaatbaar voor water maar resorbeert actief NaCl (NKCC2); zo ontstaat de concentratiegradiënt in het merg.","definition":"<p>Het <strong>opstijgende been</strong> van de lis van Henle heeft een dun en een dik deel. Het is <em>impermeabel voor water</em>.</p><p>In het dikke opstijgende deel wordt actief Na⁺, K⁺ en 2Cl⁻ opgenomen via de NKCC2-cotransporter (het aangrijpingspunt van lisdiuretica zoals furosemide). Daardoor wordt de tubulusvloeistof verdund (‘verdunnend segment’) en het interstitium van het merg hypertoon, de basis van het tegenstroommechanisme.</p>","image_url":"","wiki_title":"Loop of Henle","match":"opstijgende been van de lis van henle|opstijgend been van de lis van henle|dikke opstijgende been|opstijgende lis van henle","option_only":true},"afdalende been van de lis van henle":{"title":"Afdalende been van de lis van Henle","short":"Het afdalende been van de lis van Henle is goed doorlaatbaar voor water maar nauwelijks voor zout; water verlaat de tubulus naar het hypertone merg.","definition":"<p>Het <strong>afdalende been</strong> van de lis van Henle loopt van de cortex het niermerg in. De wand bevat veel aquaporine-1 en is daardoor <em>goed doorlaatbaar voor water</em>, maar weinig voor opgeloste stoffen.</p><p>Omdat het interstitium dieper in het merg steeds hypertoner wordt, verlaat water passief de tubulus: de tubulusvloeistof wordt geconcentreerd naar de punt van de lis toe.</p>","image_url":"","wiki_title":"Loop of Henle","match":"afdalende been van de lis van henle|afdalend been van de lis van henle|dunne afdalende been|afdalende lis van henle","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"anemie":{"title":"Anemie","short":"Anemie is een te laag hemoglobinegehalte in het bloed, waardoor het zuurstoftransport vermindert.","definition":"<p>Bij <strong>anemie</strong> is de hemoglobineconcentratie verlaagd (bij volwassenen ongeveer &lt;8,5 mmol/L bij mannen en &lt;7,5 mmol/L bij vrouwen). Klachten: moeheid, kortademigheid bij inspanning, bleekheid en hartkloppingen.</p><p>Indeling op het MCV: <em>microcytair</em> (o.a. ijzergebrek, thalassemie), <em>normocytair</em> (o.a. acuut bloedverlies, chronische ziekte, nierfalen) en <em>macrocytair</em> (o.a. vitamine B12- of foliumzuurtekort). Daarnaast onderscheidt men verminderde aanmaak van versterkte afbraak (hemolyse) of verlies.</p>","image_url":"","wiki_title":"Anemia","match":"anemie|bloedarmoede","option_only":true},"lever":{"title":"Lever","short":"De lever is de grootste klier van het lichaam: hij regelt stofwisseling van suikers, vetten en eiwitten, maakt gal en eiwitten (o.a. albumine, stollingsfactoren) en ontgift stoffen.","definition":"<p>De <strong>lever</strong> ligt rechtsboven in de buik en krijgt bloed uit de a. hepatica en (voor ±75%) uit de <em>v. portae</em>, met voedingsstoffen uit de darm.</p><p>Functies: opslag en afgifte van glucose (glycogeen, gluconeogenese), vet- en cholesterolmetabolisme, aanmaak van plasma-eiwitten (albumine, stollingsfactoren), ureumvorming, galproductie, afbraak van bilirubine en ontgifting van geneesmiddelen en alcohol. Functionele eenheden zijn de leverlobjes met hepatocyten rond sinusoïden.</p>","image_url":"","wiki_title":"Liver","match":"lever|hepar","option_only":true},"maag":{"title":"Maag","short":"De maag slaat voedsel tijdelijk op, mengt het met maagzuur en pepsine en geeft het geleidelijk af aan het duodenum.","definition":"<p>De <strong>maag</strong> bestaat uit cardia, fundus, corpus, antrum en pylorus. Het slijmvlies bevat klieren met <em>pariëtale cellen</em> (zoutzuur en intrinsieke factor), <em>hoofdcellen</em> (pepsinogeen), slijmcellen en endocriene cellen (o.a. G-cellen met gastrine in het antrum).</p><p>De maag doodt micro-organismen, start de eiwitvertering en mengt voedsel tot chymus. Intrinsieke factor is nodig voor opname van vitamine B12 in het terminale ileum.</p>","image_url":"","wiki_title":"Stomach","match":"maag|gaster|ventriculus","option_only":true},"pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"pancreas|alvleesklier","option_only":true},"galblaas":{"title":"Galblaas","short":"De galblaas slaat gal uit de lever op en dikt die in; na een vetrijke maaltijd trekt hij samen onder invloed van cholecystokinine.","definition":"<p>De <strong>galblaas</strong> ligt aan de onderzijde van de lever en is via de ductus cysticus verbonden met de galwegen. Ze slaat de gal die de lever continu maakt op en concentreert die door water en zout terug te resorberen.</p><p>Na een (vetrijke) maaltijd geeft het duodenum <em>cholecystokinine</em> af: de galblaas trekt samen en de sfincter van Oddi ontspant, zodat gal in het duodenum komt voor de vetvertering. Galstenen kunnen koliek, cholecystitis of een choledocholithiasis geven.</p>","image_url":"","wiki_title":"Gallbladder","match":"galblaas|vesica biliaris|vesica fellea","option_only":true},"de milt":{"title":"Milt","short":"De milt filtert het bloed: hij ruimt oude en beschadigde rode bloedcellen op en vormt een afweerorgaan tegen bacteriën in het bloed.","definition":"<p>De <strong>milt</strong> ligt linksboven in de buik onder het diafragma. Ze bestaat uit <em>rode pulpa</em> (sinusoïden waar verouderde of afwijkende erytrocyten worden afgebroken) en <em>witte pulpa</em> (lymfatisch weefsel met B- en T-cellen rond arteriolen).</p><p>De milt is belangrijk voor de afweer tegen <em>gekapselde bacteriën</em> (pneumokok, meningokok, H. influenzae). Na splenectomie is het risico op een ernstige sepsis daardoor verhoogd; deze patiënten worden gevaccineerd.</p>","image_url":"","wiki_title":"Spleen","match":"de milt|milt|lien|splenomegalie","option_only":true},"appendix":{"title":"Appendix","short":"De appendix is een wormvormig aanhangsel van het caecum met veel lymfatisch weefsel; ontsteking ervan (appendicitis) is een veelvoorkomende acute buik.","definition":"<p>De <strong>appendix vermiformis</strong> is een smal, blind eindigend aanhangsel van het caecum, meestal rechtsonder in de buik. De wand bevat veel lymfoïde follikels.</p><p>Bij <em>appendicitis</em> raakt het lumen afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Typisch begint de pijn rond de navel en verplaatst zich naar rechtsonder (punt van McBurney), met misselijkheid en koorts.</p>","image_url":"","wiki_title":"Appendix (anatomy)","match":"appendix|blindedarm|appendix vermiformis|wormvormig aanhangsel","option_only":true},"b-cellen":{"title":"B-cellen","short":"B-cellen zijn lymfocyten die na activatie uitrijpen tot plasmacellen die antilichamen maken; ze rijpen in het beenmerg.","definition":"<p><strong>B-cellen</strong> ontstaan en rijpen in het beenmerg. Elke B-cel draagt een unieke B-celreceptor (membraangebonden antilichaam).</p><p>Na binding van een antigeen en meestal hulp van een T-helpercel (in de kiemcentra van lymfeklieren) prolifereren ze en differentiëren ze tot <em>plasmacellen</em> (antilichaamproductie) en geheugen-B-cellen. Daarbij vinden klasseswitch en affiniteitsrijping plaats. B-cellen kunnen ook antigeen presenteren.</p>","image_url":"","wiki_title":"B cell","match":"b-cellen|b cellen|b-lymfocyten|b-cel|b-lymfocyt|b cel","option_only":true},"t-cellen":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t-cellen|t cellen|t-lymfocyten|t-cel|t-lymfocyt|t cel","option_only":true},"neutrofielen":{"title":"Neutrofiele granulocyten","short":"Neutrofielen zijn de meest voorkomende witte bloedcellen; ze zijn als eerste ter plekke bij een acute bacteriële ontsteking en fagocyteren bacteriën.","definition":"<p><strong>Neutrofiele granulocyten</strong> hebben een gesegmenteerde kern en korrels met afbrekende enzymen. Ze leven maar kort (uren tot dagen) en worden in grote aantallen in het beenmerg gemaakt.</p><p>Bij een acute ontsteking verlaten ze als eerste de bloedbaan (marginatie, rollen, adhesie, diapedese) en volgen ze chemotactische signalen (o.a. IL-8, C5a). Ze fagocyteren en doden bacteriën met een oxidatieve burst en enzymen en kunnen ‘NETs’ uitwerpen. Pus bestaat grotendeels uit dode neutrofielen.</p>","image_url":"","wiki_title":"Neutrophil","match":"neutrofielen|neutrofiele granulocyten|neutrofiel|neutrofiele granulocyt","option_only":true},"samenvatten":{"title":"Samenvatten (gesprekstechniek)","short":"Samenvatten is een gesprekstechniek waarbij de arts de kern van wat de patiënt heeft verteld kort in eigen woorden teruggeeft, om te checken en te structureren.","definition":"<p>Bij <strong>samenvatten</strong> vat de arts meerdere uitspraken of een heel gespreksdeel van de patiënt kort samen. Het doel is te controleren of de informatie goed begrepen is, overzicht te geven en het gesprek te structureren, bijvoorbeeld als afsluiting van een fase voordat een nieuw onderwerp begint.</p><p>Samenvatten gaat over de inhoud van een groter deel van het gesprek; het verschilt daarin van parafraseren, dat één uitspraak teruggeeft.</p>","image_url":"","wiki_title":"","match":"samenvatten|samenvatting geven","option_only":true},"tia":{"title":"Transient ischaemic attack (TIA)","short":"Een TIA is een kortdurende uitval van een hersenfunctie door tijdelijke ischemie, zonder blijvend infarct; een belangrijk waarschuwingssignaal voor een herseninfarct.","definition":"<p>Bij een <strong>TIA</strong> (transient ischaemic attack) ontstaan plotseling focale neurologische klachten (bijv. halfzijdige verlamming, afasie, monoculaire blindheid) die meestal binnen enkele minuten tot een uur volledig verdwijnen, zonder infarct op beeldvorming.</p><p>De oorzaak is meestal een embolie (vanuit de carotis of het hart, bijv. bij boezemfibrilleren) of een kleine-vatenafwijking. Na een TIA is het risico op een herseninfarct in de eerste dagen sterk verhoogd; snelle analyse en secundaire preventie (antistolling of plaatjesremmers, statine, bloeddruk) zijn nodig.</p>","image_url":"","wiki_title":"Transient ischemic attack","match":"tia|transient ischaemic attack|transient ischemic attack","option_only":true},"fadh2":{"title":"FADH₂","short":"FADH₂ is de gereduceerde vorm van de elektronendrager FAD; ze levert elektronen aan complex II van de elektronentransportketen.","definition":"<p><strong>FAD</strong> (flavine-adenine-dinucleotide) is een co-enzym afgeleid van riboflavine (vitamine B2). Het neemt twee elektronen en twee protonen op en wordt dan <strong>FADH₂</strong>.</p><p>FADH₂ ontstaat o.a. in de citroenzuurcyclus (succinaatdehydrogenase) en in de bèta-oxidatie van vetzuren. De elektronen gaan via complex II (en ubiquinon) de elektronentransportketen in; omdat complex I wordt overgeslagen, levert FADH₂ minder ATP op (±1,5) dan NADH (±2,5).</p>","image_url":"","wiki_title":"Flavin adenine dinucleotide","match":"fadh2|fadh₂|fad|flavine-adenine-dinucleotide","option_only":true},"nier":{"title":"Nier","short":"De nieren filteren het bloed en regelen water-, zout- en zuur-base-evenwicht en bloeddruk; ook maken ze hormonen (renine, EPO, actief vitamine D).","definition":"<p>De <strong>nieren</strong> liggen retroperitoneaal aan weerszijden van de wervelkolom. De functionele eenheid is het <em>nefron</em>: glomerulus, proximale tubulus, lis van Henle, distale tubulus en verzamelbuis. Samen filteren de nieren ongeveer 180 liter per dag, waarvan meer dan 99% wordt teruggeresorbeerd.</p><p>Ze scheiden afvalstoffen (ureum, creatinine) en geneesmiddelen uit, regelen het volume en de samenstelling van de lichaamsvloeistoffen en de pH, en maken <em>renine</em> (bloeddruk), <em>erytropoëtine</em> (aanmaak van rode bloedcellen) en <em>calcitriol</em> (actief vitamine D).</p>","image_url":"","wiki_title":"Kidney","match":"nier|nieren|ren","option_only":true},"ureter":{"title":"Ureter","short":"De ureter is de spierbuis die urine van het nierbekken naar de blaas transporteert, door peristaltiek.","definition":"<p>De <strong>ureter</strong> loopt retroperitoneaal van het nierbekken over de m. psoas naar beneden, kruist de vasa iliaca en mondt schuin uit in de blaas, waardoor terugstromen wordt voorkomen. De wand bevat <em>urotheel</em> (overgangsepitheel) en gladde spier.</p><p>Er zijn drie natuurlijke vernauwingen waar nierstenen vaak vastlopen: de overgang van nierbekken naar ureter, de kruising met de vasa iliaca en de intrede in de blaas. Bij een operatie in het bekken kan de ureter worden beschadigd (hij loopt onder de a. uterina door: ‘water onder de brug’).</p>","image_url":"","wiki_title":"Ureter","match":"ureter|urineleider|ureteren","option_only":true},"duodenum":{"title":"Duodenum (twaalfvingerige darm)","short":"Het duodenum is het eerste, C-vormige deel van de dunne darm; hier komen gal en pancreassap bij de voedselbrij.","definition":"<p>Het <strong>duodenum</strong> loopt van de pylorus in een C-bocht om de pancreaskop heen en gaat bij de flexura duodenojejunalis over in het jejunum. Het ligt grotendeels retroperitoneaal. In de pars descendens mondt via de papil van Vater de ductus choledochus samen met de ductus pancreaticus uit. Klieren van Brunner in de submucosa maken bicarbonaatrijk slijm dat het zure chymus neutraliseert; endocriene cellen maken o.a. secretine en cholecystokinine.</p>","image_url":"","wiki_title":"Duodenum","match":"duodenum|twaalfvingerige darm","option_only":true},"colon":{"title":"Colon (dikke darm)","short":"Het colon is de dikke darm van caecum tot rectum; het resorbeert water en zouten en dikt de ontlasting in.","definition":"<p>Het <strong>colon</strong> bestaat uit caecum, colon ascendens, transversum, descendens en sigmoideum, gevolgd door het rectum. Kenmerkend zijn taeniae coli, haustra en appendices epiploicae. Het slijmvlies heeft geen villi maar wel diepe crypten met veel slijmbekercellen. Het colon resorbeert water en elektrolyten, en de darmflora fermenteert vezels tot korteketenvetzuren.</p>","image_url":"","wiki_title":"Large intestine","match":"colon|dikke darm|dikkedarm","option_only":true},"caecum":{"title":"Caecum","short":"Het caecum is het blind eindigende begin van de dikke darm rechtsonder in de buik, waaraan de appendix hangt.","definition":"<p>Het <strong>caecum</strong> ligt in de rechter fossa iliaca, onder de inmonding van het ileum via de ileocaecaalklep. Aan de achter-mediale zijde hangt de appendix vermiformis. Het caecum heeft de grootste diameter van het colon en wordt doorbloed door takken van de a. ileocolica (a. mesenterica superior).</p>","image_url":"","wiki_title":"Cecum","match":"caecum|blindedarm (caecum)","option_only":true},"oesophagus":{"title":"Oesophagus (slokdarm)","short":"De oesophagus is de gespierde buis die voedsel van de keelholte naar de maag vervoert.","definition":"<p>De <strong>oesophagus</strong> is ongeveer 25 cm lang en loopt achter de trachea door het mediastinum en via de hiatus oesophageus van het diafragma naar de maag. Het slijmvlies is meerlagig onverhoornd plaveiselepitheel. Het bovenste deel bevat dwarsgestreepte, het onderste deel gladde spier. De onderste slokdarmsfincter voorkomt terugstroom van maaginhoud.</p>","image_url":"","wiki_title":"Esophagus","match":"oesophagus|slokdarm|oesofagus|esophagus","option_only":true},"blaas":{"title":"Blaas (vesica urinaria)","short":"De blaas is een gespierd hol orgaan in het kleine bekken dat urine verzamelt en bij mictie leegt.","definition":"<p>De <strong>blaas</strong> ligt achter de symfyse. De wand bestaat uit urotheel (overgangsepitheel), dat zich aanpast aan de vullingsgraad, en de m. detrusor (gladde spier). Het driehoekige trigonum ligt tussen de twee ureteruitmondingen en de urethra-opening. Vulling en lediging worden gestuurd door autonome en willekeurige zenuwen (parasympathisch: contractie van de detrusor).</p>","image_url":"","wiki_title":"Urinary bladder","match":"blaas|urineblaas|vesica urinaria","option_only":true},"nierbekken":{"title":"Nierbekken (pyelum)","short":"Het nierbekken is de trechtervormige verzamelruimte in de nier waar urine uit de kelken samenkomt voordat ze de ureter in gaat.","definition":"<p>Het <strong>nierbekken</strong> ontstaat uit de samenvloeiing van grote nierkelken (calices majores), die weer urine ontvangen uit de kleine kelken rond de nierpapillen. Het gaat bij de pyelo-ureterale overgang over in de ureter. De wand is bekleed met urotheel en bevat gladde spier die de urine voortstuwt.</p>","image_url":"","wiki_title":"Renal pelvis","match":"nierbekken|pyelum|pelvis renalis","option_only":true},"vitamine b12":{"title":"Vitamine B12 (cobalamine)","short":"Vitamine B12 is nodig voor DNA-synthese en de myelinevorming; opname vereist intrinsieke factor uit de maag en een gezond terminaal ileum.","definition":"<p><strong>Vitamine B12</strong> komt alleen uit dierlijke producten. In de maag bindt het aan intrinsieke factor (van pariëtale cellen); het complex wordt in het terminale ileum opgenomen. B12 is cofactor van methioninesynthase (koppeling met foliumzuur) en methylmalonyl-CoA-mutase. Tekort ontstaat door bijv. auto-immuungastritis (pernicieuze anemie), maag- of ileumresectie, metformine of veganisme, en geeft macrocytaire anemie en neurologische schade.</p>","image_url":"","wiki_title":"Vitamin B12","match":"vitamine b12|cobalamine|b12","option_only":true},"vitamine c":{"title":"Vitamine C (ascorbinezuur)","short":"Vitamine C is een in water oplosbare vitamine die nodig is voor de collageensynthese en werkt als antioxidant.","definition":"<p><strong>Vitamine C</strong> is cofactor van prolyl- en lysylhydroxylase, die collageen stabiliseren. Het bevordert ook de opname van non-heemijzer en werkt als antioxidant. Tekort geeft <em>scheurbuik</em>: tandvleesbloedingen, perifolliculaire bloedinkjes, slechte wondgenezing en loszittende tanden.</p>","image_url":"","wiki_title":"Vitamin C","match":"vitamine c|ascorbinezuur","option_only":true},"vitamine k":{"title":"Vitamine K","short":"Vitamine K is nodig voor de activatie van stollingsfactoren II, VII, IX en X en eiwit C en S in de lever.","definition":"<p><strong>Vitamine K</strong> is cofactor van het enzym γ-glutamylcarboxylase, dat glutamaatresten van stollingsfactoren carboxyleert zodat ze calcium kunnen binden. Cumarines (zoals acenocoumarol en fenprocoumon) remmen de recycling van vitamine K. Pasgeborenen krijgen vitamine K om bloedingen te voorkomen, omdat ze weinig voorraad en nog geen darmflora hebben.</p>","image_url":"","wiki_title":"Vitamin K","match":"vitamine k|fytomenadion|vitamine k1","option_only":true},"glutamaat":{"title":"Glutamaat (glutaminezuur)","short":"Glutamaat is de belangrijkste prikkelende neurotransmitter in het centrale zenuwstelsel en een centraal aminozuur in de stofwisseling.","definition":"<p><strong>Glutamaat</strong> werkt op ionotrope receptoren (AMPA, NMDA, kainaat) en metabotrope receptoren. NMDA-receptoren spelen een sleutelrol bij leren en geheugen (langetermijnpotentiëring). Overmatige activatie leidt tot instroom van calcium en celdood (excitotoxiciteit), bijvoorbeeld bij ischemie. In de stofwisseling is glutamaat een knooppunt van transaminering en stikstofafvoer.</p>","image_url":"","wiki_title":"Glutamic acid","match":"glutamaat|glutaminezuur|glutamate","option_only":true},"stikstofoxide":{"title":"Stikstofoxide (NO)","short":"Stikstofoxide (NO) is een gasvormige signaalstof uit het endotheel die gladde spier ontspant en zo vaten verwijdt.","definition":"<p><strong>NO</strong> wordt gemaakt uit arginine door NO-synthase. In het endotheel ontstaat het o.a. door schuifspanning en acetylcholine; het diffundeert naar de gladde spiercel, activeert guanylaatcyclase en verhoogt cGMP, wat relaxatie geeft. NO remt ook de plaatjesaggregatie. Nitraten en PDE5-remmers versterken deze route.</p>","image_url":"","wiki_title":"Nitric oxide","match":"stikstofoxide|stikstofmonoxide|no|nitric oxide","option_only":true},"a. mesenterica inferior":{"title":"A. mesenterica inferior","short":"De a. mesenterica inferior voorziet het distale derde van het colon transversum, het colon descendens, sigmoïd en bovenste rectum.","definition":"<p>De <strong>a. mesenterica inferior</strong> ontspringt ter hoogte van L3 uit de aorta abdominalis. Haar takken zijn de a. colica sinistra, de aa. sigmoideae en de a. rectalis superior. Via de arcade van Riolan en de marginale arterie (van Drummond) staat ze in verbinding met de a. mesenterica superior.</p>","image_url":"","wiki_title":"Inferior mesenteric artery","match":"a. mesenterica inferior|arteria mesenterica inferior","option_only":true},"aorta":{"title":"Aorta","short":"De aorta is de grootste slagader; ze voert zuurstofrijk bloed van de linkerventrikel naar de lichaamscirculatie.","definition":"<p>De <strong>aorta</strong> bestaat uit de aorta ascendens (met de kransslagaders), de arcus aortae (met truncus brachiocephalicus, a. carotis communis sinistra en a. subclavia sinistra), de aorta thoracica descendens en de aorta abdominalis, die ter hoogte van L4 splitst. De wand is rijk aan elastische lamellen, wat zorgt voor de windketelfunctie.</p>","image_url":"","wiki_title":"Aorta","match":"aorta|lichaamsslagader","option_only":true},"vena cava inferior":{"title":"Vena cava inferior","short":"De vena cava inferior voert het bloed uit benen, bekken en buik terug naar het rechteratrium.","definition":"<p>De <strong>vena cava inferior</strong> ontstaat ter hoogte van L5 uit de samenvloeiing van de vv. iliacae communes en loopt rechts van de aorta omhoog. Ze ontvangt o.a. de nier- en levervenen en gaat door het centrum tendineum van het diafragma (ter hoogte van T8) naar het rechteratrium.</p>","image_url":"","wiki_title":"Inferior vena cava","match":"vena cava inferior|v. cava inferior|onderste holle ader","option_only":true},"nervus vagus":{"title":"N. vagus (X)","short":"De n. vagus (X) is de belangrijkste parasympathische zenuw; hij innerveert hart, longen en het maag-darmkanaal tot het distale colon transversum.","definition":"<p>De <strong>n. vagus</strong> verlaat de schedel via het foramen jugulare en loopt in de halsvaatschede omlaag. Hij levert parasympathische vezels aan hart (vertraging), luchtwegen en darm, motorische vezels aan farynx en larynx (o.a. via de n. laryngeus recurrens) en sensibele informatie uit de inwendige organen, zoals van baroreceptoren in de aortaboog.</p>","image_url":"","wiki_title":"Vagus nerve","match":"nervus vagus|n. vagus|vagus|hersenzenuw x","option_only":true},"n. phrenicus":{"title":"N. phrenicus","short":"De n. phrenicus (C3–C5) innerveert het diafragma.","definition":"<p>De <strong>n. phrenicus</strong> ontstaat uit C3–C5 (‘C3, 4, 5 keeps the diaphragm alive’), loopt over de m. scalenus anterior naar beneden en door het mediastinum langs het pericard naar het diafragma. Hij is motorisch voor het diafragma en sensibel voor pericard, pleura en peritoneum onder het diafragma; irritatie kan daardoor pijn in de schouder geven.</p>","image_url":"","wiki_title":"Phrenic nerve","match":"n. phrenicus|nervus phrenicus","option_only":true},"tremor":{"title":"Tremor","short":"Tremor is een onwillekeurige, ritmische, oscillerende beweging van een lichaamsdeel.","definition":"<p><strong>Tremoren</strong> worden ingedeeld naar wanneer ze optreden. Een <em>rusttremor</em> (bijv. bij de ziekte van Parkinson) is aanwezig als het lichaamsdeel ontspannen is. Een <em>houdingstremor</em> (bijv. essentiële tremor, fysiologisch versterkt bij angst, cafeïne of hyperthyreoïdie) treedt op bij het vasthouden van een houding. Een <em>intentietremor</em> neemt toe bij het naderen van een doel en wijst op cerebellaire pathologie.</p>","image_url":"","wiki_title":"Tremor","match":"tremor|beven","option_only":true},"cva":{"title":"CVA (beroerte)","short":"Een CVA (beroerte) is plotselinge neurologische uitval door een herseninfarct of hersenbloeding.","definition":"<p>Een <strong>cerebrovasculair accident</strong> is in ongeveer 80% van de gevallen een herseninfarct en in de rest een hersenbloeding (intracerebraal of subarachnoïdaal). Beeldvorming (CT) is nodig om bloeding en infarct te onderscheiden, omdat de behandeling sterk verschilt. Belangrijke risicofactoren zijn hypertensie, roken, diabetes, hypercholesterolemie en boezemfibrilleren.</p>","image_url":"","wiki_title":"Stroke","match":"cva|beroerte|cerebrovasculair accident|stroke","option_only":true},"longembolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"longembolie|pulmonale embolie|longembolieën","option_only":true},"longcarcinoom":{"title":"Longcarcinoom","short":"Longkanker is een kwaadaardige tumor uitgaande van het epitheel van de luchtwegen; roken is de belangrijkste oorzaak.","definition":"<p>Het <strong>longcarcinoom</strong> wordt ingedeeld in niet-kleincellig (o.a. adenocarcinoom en plaveiselcelcarcinoom) en kleincellig longcarcinoom. Klachten zijn o.a. aanhoudende hoest, hemoptoë, kortademigheid, gewichtsverlies en recidiverende pneumonieën; vaak wordt het pas laat ontdekt. Paraneoplastische syndromen (zoals SIADH, hypercalciëmie, Lambert-Eaton) komen voor.</p>","image_url":"","wiki_title":"Lung cancer","match":"longcarcinoom|longkanker|bronchuscarcinoom","option_only":true},"ecg":{"title":"ECG (elektrocardiogram)","short":"Een ECG registreert de elektrische activiteit van het hart via elektroden op de huid.","definition":"<p>Een standaard <strong>12-afleidingen-ECG</strong> laat de P-top (boezemdepolarisatie), het QRS-complex (kamerdepolarisatie) en de T-top (repolarisatie) zien. Het wordt gebruikt om ritmestoornissen, geleidingsstoornissen, ischemie en infarct, hypertrofie en elektrolytstoornissen (bijv. hyperkaliëmie) op te sporen.</p>","image_url":"","wiki_title":"Electrocardiography","match":"ecg|elektrocardiogram|ekg","option_only":true},"paroxysmaal atriumfibrilleren":{"title":"Paroxysmaal atriumfibrilleren","short":"Bij paroxysmaal atriumfibrilleren treden aanvallen van boezemfibrilleren op die binnen 7 dagen vanzelf stoppen.","definition":"<p>Bij <strong>atriumfibrilleren</strong> is de elektrische activiteit van de boezems chaotisch; de kamers slaan onregelmatig en vaak snel. In de paroxysmale vorm duren episodes korter dan een week en eindigen ze spontaan. Er is een verhoogd risico op trombo-embolie (vooral herseninfarct) vanuit het linkerhartoor; afhankelijk van de CHA₂DS₂-VASc-score wordt antistolling gegeven.</p>","image_url":"","wiki_title":"Atrial fibrillation","match":"paroxysmaal atriumfibrilleren|paroxysmaal boezemfibrilleren|atriumfibrilleren|boezemfibrilleren","option_only":true},"ventrikelfibrilleren":{"title":"Ventrikelfibrilleren","short":"Ventrikelfibrilleren is een chaotische elektrische activiteit van de kamers zonder effectieve pompfunctie: een circulatiestilstand.","definition":"<p>Bij <strong>ventrikelfibrilleren</strong> pompt het hart geen bloed meer; binnen seconden treedt bewusteloosheid op. Het ontstaat vaak bij acute ischemie, een oud infarctlitteken, cardiomyopathie of elektrolytstoornissen. De behandeling is direct reanimeren en zo snel mogelijk defibrilleren (AED).</p>","image_url":"","wiki_title":"Ventricular fibrillation","match":"ventrikelfibrilleren|ventrikelfibrillatie|vf","option_only":true},"ventrikelseptum defect":{"title":"Ventrikelseptumdefect (VSD)","short":"Een VSD is een aangeboren opening in het septum tussen de linker- en rechterventrikel, met een links-rechtsshunt.","definition":"<p>Bij een <strong>ventrikelseptumdefect</strong> stroomt bloed in de systole van links naar rechts, wat een luid holosystolisch geruis links parasternaal geeft. Kleine (vaak musculaire) defecten sluiten vaak spontaan. Grote defecten geven volumebelasting van de longcirculatie en hartfalen op jonge leeftijd; zonder sluiting kan pulmonale hypertensie (Eisenmenger) ontstaan.</p>","image_url":"","wiki_title":"Ventricular septal defect","match":"ventrikelseptum defect|ventrikelseptumdefect|vsd","option_only":true},"open foramen ovale":{"title":"Open foramen ovale (PFO)","short":"Een open foramen ovale is een niet volledig gesloten verbinding tussen de boezems, een restant van de foetale circulatie.","definition":"<p>Het <strong>foramen ovale</strong> laat in de foetale circulatie bloed van het rechter- naar het linkeratrium stromen. Na de geboorte stijgt de druk links en sluit het functioneel; bij ongeveer een kwart van de volwassenen blijft het anatomisch open. Meestal geeft dat geen klachten, maar het kan een paradoxale embolie (veneuze stolsel naar de systeemcirculatie) mogelijk maken.</p>","image_url":"","wiki_title":"Patent foramen ovale","match":"open foramen ovale|patent foramen ovale|pfo","option_only":true},"pericarditis":{"title":"Pericarditis","short":"Pericarditis is een ontsteking van het hartzakje, met scherpe, houdingsafhankelijke pijn op de borst.","definition":"<p><strong>Pericarditis</strong> wordt meestal veroorzaakt door een virus, maar ook door bacteriën, auto-immuunziekten, nierfalen, tumoren of na een hartinfarct of hartoperatie. Typisch zijn scherpe pijn die verergert bij plat liggen en diep inademen, een pericardwrijven en diffuse ST-elevatie op het ECG. Bij veel vocht in het hartzakje kan een harttamponnade ontstaan.</p>","image_url":"","wiki_title":"Pericarditis","match":"pericarditis|hartzakontsteking","option_only":true},"sepsis":{"title":"Sepsis","short":"Sepsis is een levensbedreigende orgaandisfunctie door een ontregelde afweerreactie op een infectie.","definition":"<p>Bij <strong>sepsis</strong> leidt de reactie van het lichaam op een infectie tot schade aan de eigen organen: hypotensie, verwardheid, snelle ademhaling, nierfalen, stollingsstoornissen en een verhoogd lactaat. Septische shock is sepsis met hypotensie die vasopressoren vereist. Snelle herkenning (bijv. qSOFA), bloedkweken, antibiotica binnen een uur en vochtresuscitatie zijn essentieel.</p>","image_url":"","wiki_title":"Sepsis","match":"sepsis|bloedvergiftiging","option_only":true},"proteïnurie":{"title":"Proteïnurie","short":"Proteïnurie is verhoogd eiwitverlies in de urine, een teken van nierschade.","definition":"<p>Normaal laat de glomerulaire filter nauwelijks eiwit door, en wordt het kleine beetje gefilterd eiwit in de proximale tubulus teruggeresorbeerd. <strong>Proteïnurie</strong> ontstaat bij glomerulaire schade (bijv. diabetes, glomerulonefritis), tubulaire schade of overloop (bijv. lichte ketens bij myeloom). Bij &gt;3,5 g/dag spreekt men van nefrotische proteïnurie. Albuminurie is een vroege marker van diabetische nefropathie en vaatschade.</p>","image_url":"","wiki_title":"Proteinuria","match":"proteïnurie|eiwituitscheiding|albuminurie","option_only":true},"hyperkaliëmie":{"title":"Hyperkaliëmie","short":"Hyperkaliëmie is een te hoog kalium in het bloed; gevaarlijk door het risico op hartritmestoornissen.","definition":"<p><strong>Hyperkaliëmie</strong> ontstaat door verminderde uitscheiding (nierfalen, ACE-remmers, ARB's, kaliumsparende diuretica, hypoaldosteronisme), verschuiving uit de cel (acidose, insulinetekort, celafbraak) of overmatige inname. Op het ECG ziet men spitse T-toppen, verbrede QRS-complexen en uiteindelijk ventrikelfibrilleren. Acute behandeling: calciumgluconaat (membraanstabilisatie), insuline met glucose en salbutamol, en kalium verwijderen.</p>","image_url":"","wiki_title":"Hyperkalemia","match":"hyperkaliëmie|hyperkaliemie","option_only":true},"hypernatriëmie":{"title":"Hypernatriëmie","short":"Hypernatriëmie is een te hoog natrium in het bloed, meestal door een tekort aan water ten opzichte van zout.","definition":"<p><strong>Hypernatriëmie</strong> (&gt;145 mmol/L) ontstaat vooral als iemand onvoldoende kan drinken (ouderen, zuigelingen, verminderd bewustzijn) of water verliest via koorts, diarree of diabetes insipidus. Cellen in het brein krimpen, met sufheid, verwardheid en insulten. Correctie moet langzaam om hersenoedeem te voorkomen.</p>","image_url":"","wiki_title":"Hypernatremia","match":"hypernatriëmie|hypernatriemie","option_only":true},"hypercholesterolemie":{"title":"Hypercholesterolemie","short":"Hypercholesterolemie is een verhoogd cholesterolgehalte in het bloed, vooral van LDL-cholesterol; een risicofactor voor atherosclerose.","definition":"<p><strong>Hypercholesterolemie</strong> ontstaat door een combinatie van leefstijl en aanleg. De erfelijke vorm, familiaire hypercholesterolemie, berust meestal op een mutatie in de LDL-receptor en geeft al op jonge leeftijd zeer hoge LDL-waarden, peesxanthomen en vroege hart- en vaatziekten. Behandeling: leefstijl en statines, eventueel ezetimibe of PCSK9-remmers.</p>","image_url":"","wiki_title":"Hypercholesterolemia","match":"hypercholesterolemie|hypercholesterolaemie|verhoogd cholesterol","option_only":true},"hyperlipidemie":{"title":"Hyperlipidemie","short":"Hyperlipidemie is een verhoogd gehalte aan vetten (cholesterol en/of triglyceriden) in het bloed.","definition":"<p><strong>Hyperlipidemie</strong> kan primair (erfelijk) of secundair zijn, bijvoorbeeld bij diabetes, hypothyreoïdie, nefrotisch syndroom, alcoholgebruik of medicatie. Een verhoogd LDL is een belangrijke risicofactor voor atherosclerose; zeer hoge triglyceriden geven risico op pancreatitis.</p>","image_url":"","wiki_title":"Hyperlipidemia","match":"hyperlipidemie|dyslipidemie","option_only":true},"refluxklachten":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"refluxklachten|reflux|gastro-oesofageale reflux|zuurbranden|refluxziekte","option_only":true},"speekselvloed":{"title":"Speekselvloed (sialorroe)","short":"Speekselvloed is overmatig speeksel in de mond of kwijlen, door teveel productie of slecht slikken.","definition":"<p><strong>Sialorroe</strong> kan ontstaan door verhoogde productie (bijv. door clozapine, cholinerge middelen, misselijkheid, tandproblemen) of, vaker, door verminderd slikken of slechte mondsluiting, zoals bij de ziekte van Parkinson, ALS, een beroerte of cerebrale parese.</p>","image_url":"","wiki_title":"Drooling","match":"speekselvloed|sialorroe|hypersalivatie|kwijlen","option_only":true},"versterken en steunen":{"title":"Versterken en steunen","short":"Gesprekstechniek waarbij de arts de patiënt aanmoedigt en waardering uitspreekt voor wat goed gaat of wat de patiënt al doet.","definition":"<p>Bij <strong>versterken en steunen</strong> benoemt de arts de sterke kanten, inspanningen en eigen oplossingen van de patiënt (‘Knap dat u al zo lang volhoudt’). Dat vergroot het zelfvertrouwen en de motivatie. Het wordt o.a. gebruikt in motiverende gespreksvoering en bij het slechtnieuwsgesprek.</p>","image_url":"","wiki_title":"","match":"versterken en steunen","option_only":true},"erkennen en accepteren":{"title":"Erkennen en accepteren","short":"Gesprekstechniek waarbij de arts de beleving en emoties van de patiënt serieus neemt en laat merken dat die er mogen zijn.","definition":"<p>Bij <strong>erkennen</strong> laat de arts merken dat de gevoelens, zorgen of het standpunt van de patiënt begrijpelijk zijn, zonder het daarmee inhoudelijk eens te hoeven zijn. Dat voorkomt dat de patiënt zich onbegrepen voelt en zich gaat verdedigen. Het is een basisvaardigheid bij emoties, weerstand en slecht nieuws.</p>","image_url":"","wiki_title":"","match":"erkennen en accepteren|erkennen","option_only":true},"stiltes":{"title":"Stiltes (gesprekstechniek)","short":"Bewust stiltes laten vallen geeft de patiënt ruimte om na te denken, emoties te uiten of meer te vertellen.","definition":"<p>Een korte <strong>stilte</strong> na een vraag of na slecht nieuws laat de patiënt tijd om informatie te verwerken en zelf het woord te nemen. Veel artsen vullen stiltes te snel op. Stiltes zijn een vorm van non-verbaal aanmoedigen, naast knikken en oogcontact.</p>","image_url":"","wiki_title":"","match":"stiltes|stilte laten vallen","option_only":true},"positief her-etiketteren":{"title":"Positief her-etiketteren (reframen)","short":"Bij positief her-etiketteren geeft de arts gedrag of een uitspraak van de patiënt een andere, positievere betekenis.","definition":"<p>Bij <strong>positief her-etiketteren</strong> (reframing) wordt een negatief gelabeld gedrag in een ander licht gezet: ‘U noemt het zeuren, maar ik zie vooral iemand die goed voor zijn moeder wil zorgen.’ Het kan weerstand verminderen en nieuwe mogelijkheden openen.</p>","image_url":"","wiki_title":"","match":"positief her-etiketteren|positief heretiketteren|reframen","option_only":true},"gevoelsreflectie maken":{"title":"Gevoelsreflectie","short":"Bij een gevoelsreflectie benoemt de arts het gevoel dat hij of zij bij de patiënt waarneemt (‘U lijkt er erg van te schrikken’).","definition":"<p>Een <strong>gevoelsreflectie</strong> richt zich niet op de inhoud maar op de emotie achter de woorden of het gedrag van de patiënt. Door het gevoel te benoemen voelt de patiënt zich begrepen en krijgt hij of zij ruimte om erover te praten. Het verschilt van parafraseren, dat de inhoud teruggeeft.</p>","image_url":"","wiki_title":"","match":"gevoelsreflectie maken|een gevoelsreflectie maken|gevoelsreflectie|reflecteren van gevoelens","option_only":true},"confronteren":{"title":"Confronteren (gesprekstechniek)","short":"Bij confronteren wijst de arts de patiënt op tegenstrijdigheden in wat hij of zij zegt of doet.","definition":"<p>Bij <strong>confronteren</strong> benoemt de arts een discrepantie, bijvoorbeeld tussen woorden en gedrag (‘U zegt dat u wilt stoppen met roken, maar u bent vorige week weer begonnen’) of tussen verbale en non-verbale signalen. Goed gedoseerd en respectvol kan het tot inzicht leiden; te vroeg of te hard kan het weerstand oproepen.</p>","image_url":"","wiki_title":"","match":"confronteren|confrontatie","option_only":true},"personaliseren":{"title":"Personaliseren (gesprekstechniek)","short":"Personaliseren is een explorerende gespreksvaardigheid waarmee de arts het gesprek dichter bij de eigen ervaring van de patiënt brengt.","definition":"<p>Bij <b>personaliseren</b> wordt vaag of afstandelijk taalgebruik van de patiënt concreet en persoonlijk gemaakt, zodat duidelijk wordt wat een klacht voor deze patiënt betekent. Andere explorerende vaardigheden zijn concretiseren, doorvragen en reflecteren.</p>","image_url":"","wiki_title":"","match":"personaliseren","option_only":true},"informatiebias":{"title":"Informatiebias","short":"Informatiebias is een systematische fout in een onderzoek doordat blootstelling of uitkomst verkeerd wordt gemeten of gerapporteerd.","definition":"<p>Bij <strong>informatiebias</strong> worden deelnemers verkeerd ingedeeld (misclassificatie). Voorbeelden zijn recall bias (patiënten herinneren zich blootstelling beter dan controles), interviewerbias en meetfouten. Als de fout in beide groepen gelijk is (non-differentieel), wordt een verband meestal onderschat; als ze verschilt (differentieel), kan het verband in beide richtingen vertekend raken.</p>","image_url":"","wiki_title":"Information bias (epidemiology)","match":"informatiebias|meetbias|misclassificatie","option_only":true},"lisdiureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"lisdiureticum|lisdiuretica|furosemide|bumetanide","option_only":true},"tyrosine":{"title":"Tyrosine","short":"Tyrosine is een aminozuur dat de bouwsteen vormt voor catecholaminen, schildklierhormonen en melanine.","definition":"<p><strong>Tyrosine</strong> wordt gemaakt uit fenylalanine (door fenylalaninehydroxylase; bij fenylketonurie werkt dit enzym niet). Uit tyrosine ontstaan via tyrosinehydroxylase L-DOPA, dopamine, noradrenaline en adrenaline; daarnaast schildklierhormoon (T3/T4) en het pigment melanine.</p>","image_url":"","wiki_title":"Tyrosine","match":"tyrosine","option_only":true},"n-acetylglutamaat (glcnac)":{"title":"N-acetylglutamaat","short":"N-acetylglutamaat is de noodzakelijke activator van carbamoylfosfaatsynthetase I, de eerste stap van de ureumcyclus.","definition":"<p><strong>N-acetylglutamaat</strong> wordt in het mitochondrion van de hepatocyt gemaakt uit glutamaat en acetyl-CoA, vooral na een eiwitrijke maaltijd (gestimuleerd door arginine). Zonder N-acetylglutamaat is carbamoylfosfaatsynthetase I inactief en loopt ammoniak op. (GlcNAc is de afkorting van een ander molecuul, N-acetylglucosamine.)</p>","image_url":"","wiki_title":"N-Acetylglutamic acid","match":"n-acetylglutamaat (glcnac)|n-acetylglutamaat","option_only":true},"aceton":{"title":"Aceton (ketonlichaam)","short":"Aceton is een ketonlichaam dat ontstaat uit acetoacetaat; het geeft de zoete ‘nagellakgeur’ van de adem bij ketose.","definition":"<p>Bij vasten of insulinetekort maakt de lever uit vetzuren de <strong>ketonlichamen</strong> acetoacetaat en β-hydroxybutyraat, die door brein, hart en spier als brandstof gebruikt kunnen worden. Aceton ontstaat spontaan uit acetoacetaat, wordt niet verder gebruikt en wordt uitgeademd. Bij diabetische ketoacidose ruikt de adem daardoor fruitig.</p>","image_url":"","wiki_title":"Ketone bodies","match":"aceton|ketonlichamen|ketonen","option_only":true},"butyryl-coa":{"title":"Butyryl-CoA","short":"Butyryl-CoA is een tussenproduct van de bèta-oxidatie van vetzuren (een geactiveerd vetzuur met vier koolstofatomen).","definition":"<p><strong>Butyryl-CoA</strong> ontstaat bij de afbraak van langere vetzuren in de laatste rondes van de bèta-oxidatie. In de volgende ronde wordt het gesplitst in twee moleculen acetyl-CoA. Het is ook de geactiveerde vorm van boterzuur, dat door darmbacteriën wordt gemaakt en de brandstof is van colonepitheel.</p>","image_url":"","wiki_title":"Butyryl-CoA","match":"butyryl-coa","option_only":true},"proprionyl-coa":{"title":"Propionyl-CoA","short":"Propionyl-CoA ontstaat bij de afbraak van vetzuren met een oneven aantal koolstofatomen en van enkele aminozuren; het wordt omgezet in succinyl-CoA.","definition":"<p><strong>Propionyl-CoA</strong> wordt door propionyl-CoA-carboxylase (cofactor biotine) omgezet in methylmalonyl-CoA en daarna door methylmalonyl-CoA-mutase (cofactor vitamine B12) in succinyl-CoA, dat de citroenzuurcyclus in gaat. Een tekort aan vitamine B12 leidt daardoor tot een verhoogd methylmalonzuur.</p>","image_url":"","wiki_title":"Propionyl-CoA","match":"proprionyl-coa|propionyl-coa","option_only":true},"glomerulaire mesangiumcellen":{"title":"Mesangiumcellen","short":"Mesangiumcellen liggen tussen de capillairlissen van de glomerulus; ze geven steun, kunnen samentrekken en ruimen afzettingen op.","definition":"<p><strong>Mesangiumcellen</strong> zijn gespecialiseerde gladde-spierachtige cellen in de glomerulus. Ze maken de mesangiale matrix, kunnen het filtratieoppervlak veranderen door contractie en fagocyteren afzettingen. Bij IgA-nefropathie stapelt IgA zich op in het mesangium; ook bij diabetische nefropathie neemt de mesangiale matrix toe.</p>","image_url":"","wiki_title":"Mesangial cell","match":"glomerulaire mesangiumcellen|mesangiumcellen|mesangium","option_only":true},"vas afferens":{"title":"Vas afferens","short":"De vas afferens is de arteriool die bloed naar de glomerulus voert.","definition":"<p>De <strong>vas afferens</strong> regelt de bloedtoevoer naar de glomerulus en daarmee mede de filtratiedruk. Bij een stijgende druk trekt ze samen (myogene reflex); via de tubuloglomerulaire terugkoppeling van de macula densa wordt de diameter verder bijgestuurd. In de wand liggen de juxtaglomerulaire cellen die renine maken. Prostaglandinen verwijden haar, NSAID's vernauwen haar.</p>","image_url":"","wiki_title":"Afferent arterioles","match":"vas afferens|arteriola afferens|afferente arteriool","option_only":true},"musculeuze arterie":{"title":"Musculeuze (gespierde) arterie","short":"Musculeuze arteriën zijn middelgrote slagaders met een dikke laag gladde spier in de media, die de bloedverdeling regelen.","definition":"<p>In <strong>musculeuze arteriën</strong> (zoals de a. radialis, a. femoralis en coronairarteriën) bestaat de tunica media vooral uit gladde spiercellen, met een duidelijke lamina elastica interna en externa. Door contractie of relaxatie kunnen ze de bloedtoevoer naar organen regelen. Elastische arteriën (aorta) hebben juist veel elastische lamellen.</p>","image_url":"","wiki_title":"Artery","match":"musculeuze arterie|gespierde arterie|spierarterie","option_only":true},"postcapillaire venule":{"title":"Postcapillaire venule","short":"Postcapillaire venulen zijn de kleinste venen na de capillairen; hier verlaten leukocyten bij ontsteking de bloedbaan.","definition":"<p>De wand van <strong>postcapillaire venulen</strong> bestaat uit endotheel met pericyten. Hier is de vaatwand het meest doorlaatbaar bij ontsteking (histamine laat endotheelcellen samentrekken) en vindt de extravasatie van leukocyten plaats. In lymfeklieren hebben ze hoog endotheel (HEV), waardoor lymfocyten de klier binnengaan.</p>","image_url":"","wiki_title":"Venule","match":"postcapillaire venule|postcapillaire venulen|hoog endotheel venule","option_only":true},"gefenestreerde capillairen met een diafragma":{"title":"Gefenestreerde capillairen met diafragma","short":"Dit zijn capillairen met porieën in het endotheel die afgesloten zijn door een dun diafragma; ze komen o.a. voor in endocriene klieren en de darm.","definition":"<p>In <strong>gefenestreerde capillairen</strong> bevat het endotheel kleine openingen (fenestrae) van ongeveer 60–80 nm. Bij het type <em>met diafragma</em> worden deze afgedekt door een dun eiwitvlies. Ze laten snelle uitwisseling van kleine moleculen toe en komen voor in endocriene klieren, darmvlokken en de plexus choroideus.</p>","image_url":"","wiki_title":"Capillary","match":"gefenestreerde capillairen met een diafragma|gefenestreerde capillairen met diafragma","option_only":true},"gefenestreerde capillairen zonder diafragma":{"title":"Gefenestreerde capillairen zonder diafragma","short":"Gefenestreerde capillairen zonder diafragma hebben open poriën in het endotheel; het klassieke voorbeeld is de glomerulus.","definition":"<p>In de <strong>glomerulus</strong> hebben de capillairen grote fenestrae zonder diafragma, liggend op een dikke basaalmembraan. Dat maakt een zeer hoge filtratie van water en kleine moleculen mogelijk, terwijl basaalmembraan en podocyten grote eiwitten tegenhouden.</p>","image_url":"","wiki_title":"Capillary","match":"gefenestreerde capillairen zonder diafragma","option_only":true},"discontinue sinusoïden":{"title":"Discontinue (sinusoïdale) capillairen","short":"Sinusoïden zijn wijde capillairen met grote openingen tussen de endotheelcellen en een onvolledige basaalmembraan, o.a. in lever, milt en beenmerg.","definition":"<p>In <strong>sinusoïdale capillairen</strong> kunnen grote moleculen en soms cellen de vaatwand passeren. In de lever liggen ze tussen de balkjes hepatocyten; daar zit tussen endotheel en hepatocyten de ruimte van Disse. In milt en beenmerg laten ze bloedcellen door.</p>","image_url":"","wiki_title":"Capillary","match":"discontinue sinusoïden|sinusoïden|sinusoïdale capillairen|discontinue capillairen","option_only":true},"eenlagig plaveiselepitheel":{"title":"Eenlagig plaveiselepitheel","short":"Eenlagig plaveiselepitheel bestaat uit één laag platte cellen en is geschikt voor diffusie en filtratie.","definition":"<p><strong>Eenlagig plaveiselepitheel</strong> bekleedt de alveoli (pneumocyten type I), de binnenkant van bloed- en lymfevaten (endotheel), de sereuze vliezen (mesotheel) en het pariëtale blad van het kapsel van Bowman. Door de geringe dikte is snelle uitwisseling van gassen en stoffen mogelijk.</p>","image_url":"","wiki_title":"Simple squamous epithelium","match":"eenlagig plaveiselepitheel","option_only":true},"meerlagig onverhoornend plaveiselepitheel":{"title":"Meerlagig onverhoornd plaveiselepitheel","short":"Meerlagig onverhoornd plaveiselepitheel beschermt vochtige oppervlakken tegen mechanische belasting, zoals mond, slokdarm en vagina.","definition":"<p>In <strong>meerlagig onverhoornd plaveiselepitheel</strong> worden de cellen naar boven toe platter, maar ze behouden hun kern en verhoornen niet. Het komt voor in mondholte, oesophagus, vagina, ectocervix en cornea. Het verhoornde type vormt de epidermis van de huid.</p>","image_url":"","wiki_title":"Stratified squamous epithelium","match":"meerlagig onverhoornend plaveiselepitheel|meerlagig onverhoornd plaveiselepitheel","option_only":true},"meerrijig plaveiselepitheel":{"title":"Meerrijig (pseudostratified) epitheel","short":"Meerrijig epitheel lijkt meerlagig, maar alle cellen raken de basaalmembraan; met trilharen bekleedt het de luchtwegen.","definition":"<p>In <strong>meerrijig epitheel</strong> liggen de kernen op verschillende hoogtes, waardoor het meerlagig lijkt, terwijl elke cel contact maakt met de basaalmembraan. Het klassieke voorbeeld is het respiratoire epitheel (meerrijig trilhaarcilinderepitheel met slijmbekercellen) in neus, trachea en bronchi. Een ‘meerrijig plaveiselepitheel’ bestaat strikt genomen niet.</p>","image_url":"","wiki_title":"Pseudostratified columnar epithelium","match":"meerrijig plaveiselepitheel|meerrijig epitheel|meerrijig trilhaarcilinderepitheel","option_only":true},"cloaca":{"title":"Cloaca","short":"De cloaca is het gemeenschappelijke eindstuk van de embryonale achterdarm, waarin ook de allantois uitmondt.","definition":"<p>Het urorectale septum verdeelt de <strong>cloaca</strong> in een dorsaal deel (rectum en bovenste anaalkanaal) en een ventraal deel, de sinus urogenitalis (blaas en urethra). Het cloacamembraan scheurt later. Een stoornis in deze verdeling geeft anorectale misvormingen en fistels.</p>","image_url":"","wiki_title":"Cloaca (embryology)","match":"cloaca","option_only":true},"hernia diafragmatica":{"title":"Hernia diafragmatica","short":"Bij een hernia diafragmatica liggen buikorganen via een defect in het diafragma in de borstholte.","definition":"<p>De <strong>congenitale hernia diafragmatica</strong> ontstaat meestal links-achter (hernia van Bochdalek) doordat de pleuroperitoneale membranen niet goed sluiten. Darmen en soms maag en lever liggen in de thorax en belemmeren de groei van de long (longhypoplasie, pulmonale hypertensie). De pasgeborene is direct na de geboorte benauwd met een ingevallen buik.</p>","image_url":"","wiki_title":"Congenital diaphragmatic hernia","match":"hernia diafragmatica|congenitale hernia diafragmatica|hernia van bochdalek","option_only":true},"hypokaliëmie":{"title":"Hypokaliëmie","short":"Hypokaliëmie is een te laag kalium in het bloed, met spierzwakte, obstipatie en hartritmestoornissen als risico.","definition":"<p><strong>Hypokaliëmie</strong> ontstaat door verlies via nier (diuretica, hyperaldosteronisme, braken met metabole alkalose) of darm (diarree, laxantia), door verschuiving de cel in (insuline, β2-agonisten, alkalose) of zelden door te weinig inname. Op het ECG ziet men afgeplatte T-toppen en U-golven; het risico op aritmieën stijgt, vooral bij digoxinegebruik. Hypomagnesiëmie moet ook worden gecorrigeerd.</p>","image_url":"","wiki_title":"Hypokalemia","match":"hypokaliëmie|hypokaliemie","option_only":true},"hyponatriëmie":{"title":"Hyponatriëmie","short":"Hyponatriëmie is een te laag natrium in het bloed, meestal door een relatief overschot aan water.","definition":"<p><strong>Hyponatriëmie</strong> (&lt;135 mmol/L) wordt ingedeeld naar de volumestatus: ondervuld (bijv. braken, diuretica), normovolemisch (bijv. SIADH, hypothyreoïdie, bijnierinsufficiëntie) of overvuld (hartfalen, cirrose, nierfalen). Ernstige of snel ontstane hyponatriëmie geeft hersenoedeem met verwardheid, insulten en coma. Te snelle correctie kan osmotische demyelinisatie veroorzaken.</p>","image_url":"","wiki_title":"Hyponatremia","match":"hyponatriëmie|hyponatriemie","option_only":true},"atriumseptum defect":{"title":"Atriumseptumdefect (ASD)","short":"Een ASD is een aangeboren opening in het septum tussen de boezems, met een links-rechtsshunt.","definition":"<p>Bij een <strong>atriumseptumdefect</strong> (meestal type secundum) stroomt bloed van het linker- naar het rechteratrium, met volumebelasting van het rechterhart en de longcirculatie. Het geeft vaak pas op volwassen leeftijd klachten (vermoeidheid, kortademigheid, boezemfibrilleren). Kenmerkend is een vaste splijting van de tweede harttoon. Sluiting kan meestal via een katheter.</p>","image_url":"","wiki_title":"Atrial septal defect","match":"atriumseptum defect|atriumseptumdefect|asd","option_only":true},"transpositie van de grote vaten":{"title":"Transpositie van de grote arteriën","short":"Bij transpositie van de grote arteriën komt de aorta uit de rechterventrikel en de a. pulmonalis uit de linker, met twee gescheiden circulaties.","definition":"<p>Bij <strong>TGA</strong> is overleven na de geboorte alleen mogelijk via menging van bloed (foramen ovale, ductus arteriosus, VSD). De pasgeborene is direct na de geboorte ernstig cyanotisch. Prostaglandine houdt de ductus open en een ballonatrioseptostomie verbetert de menging, waarna een arteriële switchoperatie volgt.</p>","image_url":"","wiki_title":"Transposition of the great arteries","match":"transpositie van de grote vaten|transpositie van de grote arteriën|tga","option_only":true},"longoedeem":{"title":"Longoedeem","short":"Longoedeem is vocht in het interstitium en de alveoli van de longen, met ernstige kortademigheid.","definition":"<p><strong>Cardiaal longoedeem</strong> ontstaat door een verhoogde druk in het linkeratrium en de longcapillairen (bijv. linkszijdig hartfalen, mitralisstenose). Klachten: kortademigheid, orthopneu, crepitaties en soms roze schuimend sputum. Niet-cardiaal longoedeem ontstaat door beschadiging van de alveolocapillaire wand (ARDS). Behandeling o.a. met zuurstof, diuretica en nitraten.</p>","image_url":"","wiki_title":"Pulmonary edema","match":"longoedeem","option_only":true},"hypoxie":{"title":"Hypoxie","short":"Hypoxie is een tekort aan zuurstof in weefsels; hypoxemie is een te lage zuurstofspanning in het bloed.","definition":"<p>Oorzaken van <strong>hypoxemie</strong> zijn hypoventilatie, ventilatie-perfusiemismatch, shunt, diffusiestoornis en een lage zuurstofspanning in de ingeademde lucht (hoogte). Weefselhypoxie kan ook ontstaan bij anemie, koolmonoxidevergiftiging, verminderde doorbloeding of mitochondriale vergiftiging (cyanide). Cellen schakelen dan over op anaerobe stofwisseling, met lactaatvorming.</p>","image_url":"","wiki_title":"Hypoxia (medicine)","match":"hypoxie|hypoxemie|zuurstoftekort","option_only":true},"vasodilatatie":{"title":"Vasodilatatie","short":"Vasodilatatie is verwijding van bloedvaten door ontspanning van de gladde spier in de vaatwand.","definition":"<p><strong>Vasodilatatie</strong> verlaagt de vaatweerstand en verhoogt de doorbloeding. Mediatoren zijn o.a. NO, prostacycline, histamine, bradykinine, adenosine, CO₂ en melkzuur (lokale autoregulatie). Het speelt een rol bij ontsteking (roodheid en warmte), warmteafgifte en inspanning, en is het werkingsmechanisme van veel antihypertensiva.</p>","image_url":"","wiki_title":"Vasodilation","match":"vasodilatatie|vaatverwijding","option_only":true},"perifeer oedeem":{"title":"Perifeer oedeem","short":"Perifeer oedeem is vochtophoping in de benen en voeten, vaak putjes achterlatend bij indrukken.","definition":"<p><strong>Perifeer oedeem</strong> ontstaat door een verhoogde veneuze druk (rechtszijdig hartfalen, veneuze insufficiëntie, trombose), een laag albumine (nefrotisch syndroom, cirrose, ondervoeding), medicatie (calciumantagonisten, NSAID's) of lymfoedeem. Eenzijdig oedeem past vaker bij een lokale oorzaak, zoals trombose of cellulitis.</p>","image_url":"","wiki_title":"Edema","match":"perifeer oedeem|enkeloedeem","option_only":true},"microscopische hematurie":{"title":"Microscopische hematurie","short":"Bij microscopische hematurie zijn rode bloedcellen alleen met de microscoop of een teststrook in de urine aantoonbaar.","definition":"<p><strong>Hematurie</strong> kan glomerulair zijn (dysmorfe erytrocyten, erytrocytencilinders, vaak met proteïnurie; bijv. IgA-nefropathie) of niet-glomerulair (stenen, infecties, tumoren van nier, ureter of blaas). Bij ouderen en rokers moet bij hematurie een urologische maligniteit worden uitgesloten.</p>","image_url":"","wiki_title":"Hematuria","match":"microscopische hematurie|hematurie","option_only":true},"leucocyturie":{"title":"Leukocyturie","short":"Leukocyturie is de aanwezigheid van witte bloedcellen in de urine, meestal bij een urineweginfectie.","definition":"<p><strong>Leukocyturie</strong> wordt aangetoond met een teststrook (leukocytenesterase) of microscopie. Meestal past het bij een bacteriële urineweginfectie, eventueel samen met positief nitriet. ‘Steriele’ leukocyturie zonder groei in de kweek komt voor bij o.a. chlamydia, urogenitale tuberculose, tubulo-interstitiële nefritis en na antibioticagebruik.</p>","image_url":"","wiki_title":"Pyuria","match":"leucocyturie|leukocyturie|pyurie","option_only":true},"lobaire pneumonie, veroorzaakt door pneumokokken":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"lobaire pneumonie, veroorzaakt door pneumokokken","option_only":true},"diabetes type 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes type 2","option_only":true},"het beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"het beenmerg","option_only":true},"thiazide diureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazide diureticum","option_only":true},"t cel":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t cel","option_only":true},"b cel":{"title":"B-cellen","short":"B-cellen zijn lymfocyten die na activatie uitrijpen tot plasmacellen die antilichamen maken; ze rijpen in het beenmerg.","definition":"<p><strong>B-cellen</strong> ontstaan en rijpen in het beenmerg. Elke B-cel draagt een unieke B-celreceptor (membraangebonden antilichaam).</p><p>Na binding van een antigeen en meestal hulp van een T-helpercel (in de kiemcentra van lymfeklieren) prolifereren ze en differentiëren ze tot <em>plasmacellen</em> (antilichaamproductie) en geheugen-B-cellen. Daarbij vinden klasseswitch en affiniteitsrijping plaats. B-cellen kunnen ook antigeen presenteren.</p>","image_url":"","wiki_title":"B cell","match":"b cel","option_only":true},"diabetes mellitus 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus 2","option_only":true},"overmatig alcoholgebruik":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"overmatig alcoholgebruik","option_only":true},"tunica intima":{"title":"Tunica intima","short":"De tunica intima is de binnenste laag van de vaatwand, bekleed met endotheel.","definition":"<p>De <strong>tunica intima</strong> bestaat uit endotheel op een basaalmembraan met een dun laagje subendotheliaal bindweefsel; in arteriën ligt eronder de lamina elastica interna. Het endotheel regelt vaattonus, stolling en de passage van stoffen en cellen.</p>","image_url":"","wiki_title":"Tunica intima","match":"tunica intima|intima","option_only":true},"av-block":{"title":"AV-blok","short":"Een AV-blok is een vertraagde of geblokkeerde geleiding van de prikkel van de boezems naar de kamers.","definition":"<p>Bij een <strong>eerstegraads AV-blok</strong> is het PR-interval verlengd. Bij een <strong>tweedegraads</strong> blok vallen sommige QRS-complexen weg (Wenckebach: geleidelijke PR-verlenging; Mobitz II: plotseling, gevaarlijker). Bij een <strong>derdegraads</strong> (totaal) blok kloppen boezems en kamers onafhankelijk, met een traag escaperitme. Oorzaken: degeneratie, ischemie, medicatie, ziekte van Lyme, sarcoïdose, aangeboren (maternale anti-SSA).</p>","image_url":"","wiki_title":"Atrioventricular block","match":"av-block|av-blok|atrioventriculair blok|atrioventriculaire geleidingsstoornissen|atroventriculaire geleidingsstoornissen","option_only":true},"troponine t":{"title":"Troponine","short":"Troponine is een eiwit uit de hartspier; een stijging in het bloed wijst op schade aan hartspiercellen.","definition":"<p><strong>Cardiaal troponine</strong> (T of I) komt vrij bij beschadiging van myocyten. Het is de belangrijkste marker voor een myocardinfarct: het stijgt binnen enkele uren en blijft dagen verhoogd. Ook bij myocarditis, longembolie, hartfalen, sepsis, nierfalen en na zware inspanning kan het stijgen. Met hooggevoelige tests wordt naar de verandering in de tijd gekeken.</p>","image_url":"","wiki_title":"Troponin","match":"troponine t|troponine|troponine i|hs-troponine","option_only":true},"paniekaanval":{"title":"Paniekaanval","short":"Een paniekaanval is een plotselinge golf van intense angst met lichamelijke klachten, die binnen minuten een piek bereikt.","definition":"<p>Tijdens een <strong>paniekaanval</strong> ontstaan o.a. hartkloppingen, zweten, trillen, benauwdheid, druk op de borst, duizeligheid, tintelingen en angst om dood te gaan of gek te worden. Bij een <strong>paniekstoornis</strong> zijn er herhaalde, onverwachte aanvallen met aanhoudende angst voor nieuwe aanvallen. Behandeling met cognitieve gedragstherapie en/of SSRI's.</p>","image_url":"","wiki_title":"Panic attack","match":"paniekaanval|paniekstoornis","option_only":true},"blaasretentie":{"title":"Urineretentie","short":"Bij urineretentie kan iemand de blaas niet (volledig) legen, acuut met pijnlijke volle blaas of chronisch met overloopincontinentie.","definition":"<p><strong>Urineretentie</strong> ontstaat door een obstructie (prostaatvergroting, urethrastrictuur, stolsels), medicatie (anticholinergica, opioïden), neurologische oorzaken (dwarslaesie, cauda-equinasyndroom, diabetische neuropathie) of na operaties en anesthesie. Acute retentie wordt behandeld met een katheter.</p>","image_url":"","wiki_title":"Urinary retention","match":"blaasretentie|urineretentie|retentieblaas","option_only":true},"aortadissectie, type a":{"title":"Aortadissectie","short":"Bij een aortadissectie scheurt de binnenwand van de aorta, waardoor bloed tussen de wandlagen stroomt; type A betreft de aorta ascendens en is een chirurgisch spoedgeval.","definition":"<p>Een <strong>aortadissectie</strong> geeft plotselinge, zeer hevige, scheurende pijn in borst of rug, soms met een bloeddrukverschil tussen de armen, een nieuw diastolisch geruis of neurologische uitval. Risicofactoren: hypertensie, bindweefselziekten (Marfan), bicuspide klep en cocaïne. Type A (aorta ascendens) vereist een spoedoperatie; type B wordt vaak eerst medicamenteus behandeld.</p>","image_url":"","wiki_title":"Aortic dissection","match":"aortadissectie, type a|aortadissectie|dissectie thoracale aorta|dissectie van de aorta","option_only":true},"glomerulaire basale membraan":{"title":"Glomerulaire basaalmembraan","short":"De glomerulaire basaalmembraan ligt tussen het endotheel en de podocyten en houdt samen met hen eiwitten tegen bij de filtratie.","definition":"<p>De <strong>GBM</strong> bestaat o.a. uit collageen type IV en heparansulfaat en is negatief geladen, waardoor ook albumine wordt tegengehouden. Bij het syndroom van Alport is collageen IV afwijkend; bij anti-GBM-ziekte (Goodpasture) vallen antistoffen de GBM aan, met een snel progressieve glomerulonefritis en longbloedingen.</p>","image_url":"","wiki_title":"Glomerular basement membrane","match":"glomerulaire basale membraan|glomerulaire basaalmembraan","option_only":true},"juxtaglomerulaire cellen":{"title":"Juxtaglomerulaire cellen","short":"Juxtaglomerulaire cellen in de wand van de vas afferens maken renine, als reactie op lage druk, weinig natrium bij de macula densa of sympathische prikkeling.","definition":"<p>Het <strong>juxtaglomerulaire apparaat</strong> bestaat uit de juxtaglomerulaire cellen (gemodificeerde gladde spiercellen van de vas afferens), de macula densa (in de distale tubulus) en extraglomerulaire mesangiumcellen. Het regelt via renine het RAAS en via tubuloglomerulaire terugkoppeling de filtratie van het eigen nefron.</p>","image_url":"","wiki_title":"Juxtaglomerular apparatus","match":"juxtaglomerulaire cellen|juxtaglomerulaire apparaat|juxtaglomerulair apparaat","option_only":true},"carboanhydraseremmer":{"title":"Carboanhydraseremmer (acetazolamide)","short":"Carboanhydraseremmers zoals acetazolamide remmen de terugresorptie van bicarbonaat in de proximale tubulus.","definition":"<p><strong>Acetazolamide</strong> geeft een zwakke diurese met verlies van bicarbonaat (metabole acidose) en kalium. Het wordt gebruikt bij glaucoom (minder kamerwaterproductie), hoogteziekte, idiopathische intracraniële hypertensie en soms metabole alkalose.</p>","image_url":"","wiki_title":"Acetazolamide","match":"carboanhydraseremmer|acetazolamide|behandeling met een carboanhydraseremmer","option_only":true},"citrulline":{"title":"Citrulline","short":"Citrulline is een aminozuur en tussenproduct van de ureumcyclus, gevormd uit ornithine en carbamoylfosfaat.","definition":"<p>In het mitochondrion van de hepatocyt zet ornithinetranscarbamylase <strong>ornithine</strong> en carbamoylfosfaat om in <strong>citrulline</strong>, dat naar het cytosol gaat en met aspartaat argininosuccinaat vormt. Daaruit ontstaat arginine, dat wordt gesplitst in ureum en ornithine. Citrulline ontstaat ook bij de vorming van NO uit arginine.</p>","image_url":"","wiki_title":"Citrulline","match":"citrulline","option_only":true},"ornithine":{"title":"Ornithine","short":"Ornithine is een aminozuur in de ureumcyclus dat steeds opnieuw wordt gebruikt als drager.","definition":"<p><strong>Ornithine</strong> ontstaat bij het splitsen van arginine in ureum en ornithine (door arginase), en wordt in het mitochondrion met carbamoylfosfaat weer omgezet in citrulline. Ornithinetranscarbamylasedeficiëntie is de meest voorkomende erfelijke ureumcyclusstoornis (X-gebonden).</p>","image_url":"","wiki_title":"Ornithine","match":"ornithine","option_only":true},"arginine":{"title":"Arginine","short":"Arginine is een aminozuur waaruit in de ureumcyclus ureum ontstaat en waaruit NO-synthase stikstofmonoxide maakt.","definition":"<p>In de lever splitst arginase <strong>arginine</strong> in ureum en ornithine. In endotheel en andere cellen is arginine het substraat voor NO-synthase. Arginine stimuleert ook de afgifte van groeihormoon en insuline, en activeert de vorming van N-acetylglutamaat.</p>","image_url":"","wiki_title":"Arginine","match":"arginine|arganine","option_only":true},"glycine":{"title":"Glycine","short":"Glycine is het kleinste aminozuur en ook een remmende neurotransmitter in hersenstam en ruggenmerg.","definition":"<p><strong>Glycine</strong> komt veel voor in collageen (elke derde positie). Als neurotransmitter opent het chloridekanalen; strychnine en het tetanustoxine (dat de afgifte remt) verstoren deze remming, met krampen als gevolg. Glycine is ook een co-agonist van de NMDA-receptor.</p>","image_url":"","wiki_title":"Glycine","match":"glycine","option_only":true},"methionine":{"title":"Methionine","short":"Methionine is een essentieel, zwavelhoudend aminozuur; het start de eiwitsynthese en levert via S-adenosylmethionine methylgroepen.","definition":"<p>Methionine wordt omgezet in <strong>S-adenosylmethionine</strong>, de belangrijkste methyldonor (DNA, neurotransmitters). Daarbij ontstaat homocysteïne, dat met vitamine B12 en foliumzuur weer methionine wordt of via vitamine B6 tot cysteïne wordt omgezet. Een tekort aan deze vitamines verhoogt het homocysteïne.</p>","image_url":"","wiki_title":"Methionine","match":"methionine","option_only":true},"n-acetylglucosamine":{"title":"N-acetylglucosamine (GlcNAc)","short":"N-acetylglucosamine is een aminosuiker en bouwsteen van peptidoglycaan, chitine, hyaluronzuur en glycoproteïnen.","definition":"<p><strong>GlcNAc</strong> vormt met N-acetylmuraminezuur de suikerketens van bacterieel peptidoglycaan. Het komt ook voor in hyaluronzuur en andere glycosaminoglycanen en als modificatie van eiwitten (O-GlcNAc).</p>","image_url":"","wiki_title":"N-Acetylglucosamine","match":"n-acetylglucosamine|glcnac","option_only":true},"ribose-5-fosfaat":{"title":"Ribose-5-fosfaat","short":"Ribose-5-fosfaat is een suikerfosfaat uit de pentosefosfaatroute en de bouwsteen voor nucleotiden.","definition":"<p>De <strong>pentosefosfaatroute</strong> levert NADPH (voor vetzuursynthese en het beschermen van erytrocyten tegen oxidatieve schade) en <strong>ribose-5-fosfaat</strong> voor de synthese van DNA en RNA. Glucose-6-fosfaatdehydrogenase is het eerste enzym; een tekort geeft hemolyse bij oxidatieve stress.</p>","image_url":"","wiki_title":"Ribose 5-phosphate","match":"ribose-5-fosfaat","option_only":true},"mevalonzuur":{"title":"Mevalonzuur","short":"Mevalonzuur ontstaat uit HMG-CoA en is het eerste specifieke tussenproduct van de cholesterolsynthese.","definition":"<p>HMG-CoA-reductase zet HMG-CoA om in <strong>mevalonzuur</strong>; dit is de snelheidsbepalende stap die door statines wordt geremd. Uit mevalonaat ontstaan via isoprenoïden cholesterol, maar ook ubiquinon (co-enzym Q10) en dolichol.</p>","image_url":"","wiki_title":"Mevalonic acid","match":"mevalonzuur|mevalonaat","option_only":true},"pronefros":{"title":"Pronefros","short":"De pronefros is het eerste, niet-functionele embryonale niersysteem, dat snel weer verdwijnt.","definition":"<p>De nier ontwikkelt zich in drie opeenvolgende stelsels uit het intermediair mesoderm: <strong>pronefros</strong> (cervicaal, week 4, verdwijnt), mesonefros (functioneert tijdelijk; de gang van Wolff blijft bestaan) en metanefros (de definitieve nier vanaf week 5).</p>","image_url":"","wiki_title":"Pronephros","match":"pronefros|voornier","option_only":true},"mesonefros":{"title":"Mesonefros (oernier)","short":"De mesonefros is de tijdelijke embryonale nier; zijn afvoergang (gang van Wolff) vormt bij de man de geslachtsgangen.","definition":"<p>De <strong>mesonefros</strong> produceert kort urine in de eerste maanden van de zwangerschap en verdwijnt dan grotendeels. De ductus mesonephricus (Wolff) blijft bij de man bestaan als epididymis, ductus deferens en vesicula seminalis; uit zijn uitstulping ontstaat de ureterknop van de metanefros.</p>","image_url":"","wiki_title":"Mesonephros","match":"mesonefros|oernier|mesonephros","option_only":true},"sinus urogenitalis":{"title":"Sinus urogenitalis","short":"De sinus urogenitalis is het ventrale deel van de cloaca, waaruit blaas, urethra en (bij de vrouw) het onderste deel van de vagina ontstaan.","definition":"<p>Het urorectale septum verdeelt de cloaca in rectum (dorsaal) en <strong>sinus urogenitalis</strong> (ventraal). Daaruit ontstaan de blaas, de urethra (bij de man ook de prostaat) en bij de vrouw het vestibulum en een deel van de vagina.</p>","image_url":"","wiki_title":"Urogenital sinus","match":"sinus urogenitalis","option_only":true},"urachus":{"title":"Urachus","short":"De urachus is de embryonale verbinding tussen blaas en navel (restant van de allantois), die normaal verbindweefselt.","definition":"<p>Na de geboorte wordt de <strong>urachus</strong> een bindweefselstreng (lig. umbilicale medianum). Blijft hij (deels) open, dan kunnen een urachusfistel (urine uit de navel), een cyste of een sinus ontstaan, met risico op infectie en zelden een carcinoom.</p>","image_url":"","wiki_title":"Urachus","match":"urachus","option_only":true},"ureterknop":{"title":"Ureterknop","short":"De ureterknop is een uitstulping van de gang van Wolff die in het metanefrogene mesoderm groeit en de ureter, het nierbekken en de verzamelbuizen vormt.","definition":"<p>De wederzijdse inductie tussen <strong>ureterknop</strong> en metanefrogeen mesenchym is essentieel: het mesenchym vormt de nefronen (van glomerulus tot distale tubulus). Een dubbele ureterknop geeft een dubbelsysteem; het uitblijven van de knop leidt tot nieragenesie.</p>","image_url":"","wiki_title":"Ureteric bud","match":"ureterknop|ureteric bud","option_only":true},"pericardium":{"title":"Pericard (hartzakje)","short":"Het pericard is het hartzakje: een fibreuze buitenlaag met een sereus dubbelblad, met daartussen een laagje vocht.","definition":"<p>Het <strong>pericard</strong> bestaat uit het fibreuze pericard en het sereuze pericard (pariëtaal en visceraal blad, het epicard). Het fixeert het hart, beperkt overmatige vulling en vermindert wrijving. Ontsteking heet pericarditis; snelle vochtophoping kan een harttamponnade geven, chronische verdikking een constrictieve pericarditis.</p>","image_url":"","wiki_title":"Pericardium","match":"pericardium|pericard|hartzakje","option_only":true},"mesotheel":{"title":"Mesotheel","short":"Mesotheel is het eenlagige plaveiselepitheel dat de sereuze holten (pleura, pericard, peritoneum) bekleedt.","definition":"<p><strong>Mesotheelcellen</strong> maken een glijvloeistof die wrijving tussen organen vermindert. Een kwaadaardige tumor ervan heet mesothelioom en hangt sterk samen met eerdere blootstelling aan asbest.</p>","image_url":"","wiki_title":"Mesothelium","match":"mesotheel|mesotheelcellen","option_only":true},"juxtaglomerulaire apparaat":{"title":"Juxtaglomerulair apparaat","short":"Het juxtaglomerulaire apparaat regelt via renine de bloeddruk en via terugkoppeling de filtratie per nefron.","definition":"<p>Het bestaat uit de juxtaglomerulaire cellen van de vas afferens (renine), de macula densa van de distale tubulus (meet natriumchloride) en extraglomerulaire mesangiumcellen.</p>","image_url":"","wiki_title":"Juxtaglomerular apparatus","match":"juxtaglomerulaire apparaat","option_only":true},"ramus interventricularis posterior":{"title":"Ramus interventricularis posterior","short":"De ramus interventricularis posterior loopt aan de onderkant van het hart en voorziet het achterste deel van het septum; hij bepaalt de ‘dominantie’.","definition":"<p>De <strong>RIVP</strong> komt bij de meeste mensen uit de rechter kransslagader (rechtsdominant), bij een minderheid uit de ramus circumflexus (linksdominant). Hij voorziet het achterste derde van het ventrikelseptum en de onderwand; meestal komt ook de tak naar de AV-knoop uit de dominante arterie.</p>","image_url":"","wiki_title":"Posterior interventricular artery","match":"ramus interventricularis posterior|ripa|posterior descending artery","option_only":true},"arteriolen":{"title":"Arteriolen","short":"Arteriolen zijn de kleinste arteriën met een spierwand; ze bepalen het grootste deel van de perifere vaatweerstand.","definition":"<p>In <strong>arteriolen</strong> daalt de bloeddruk het sterkst. Door samen te trekken of te verwijden regelen ze de doorbloeding van weefsels (autoregulatie, sympathische invloed, lokale metabolieten) en daarmee de bloeddruk. Bij langdurige hypertensie of diabetes ontstaat arteriolosclerose (hyaliene verdikking).</p>","image_url":"","wiki_title":"Arteriole","match":"arteriolen|arteriool","option_only":true},"capillairen":{"title":"Capillairen","short":"Capillairen zijn de kleinste bloedvaten, met een wand van één laag endotheel, waar de uitwisseling tussen bloed en weefsel plaatsvindt.","definition":"<p>Er zijn <strong>continue</strong> capillairen (o.a. spier, huid, brein: bloed-hersenbarrière), <strong>gefenestreerde</strong> capillairen (nier, darm, endocriene klieren) en <strong>sinusoïdale</strong> capillairen (lever, milt, beenmerg). Volgens Starling bepalen hydrostatische en colloïd-osmotische druk de vochtverplaatsing over de wand.</p>","image_url":"","wiki_title":"Capillary","match":"capillairen|haarvaten|capillair","option_only":true},"chylomicronen":{"title":"Chylomicronen","short":"Chylomicronen zijn grote lipoproteïnen die vetten uit de voeding via de lymfe naar het bloed vervoeren.","definition":"<p><strong>Chylomicronen</strong> worden in enterocyten gemaakt uit triglyceriden, cholesterol en apoB-48 en via de lymfe (ductus thoracicus) afgegeven. Lipoproteïnelipase splitst hun triglyceriden; de resten (remnants) worden door de lever opgenomen. Na een vetrijke maaltijd kan het plasma daardoor melkachtig zijn.</p>","image_url":"","wiki_title":"Chylomicron","match":"chylomicronen|chylomicron","option_only":true},"turbulente flow":{"title":"Turbulente stroming","short":"Bij turbulente stroming bewegen bloeddeeltjes wanordelijk in plaats van in lagen; dat is hoorbaar als souffle of geruis.","definition":"<p>Normaal stroomt bloed <strong>laminair</strong>. Turbulentie ontstaat bij een hoge stroomsnelheid, een vernauwing (stenose), lekkende kleppen of een lage viscositeit (anemie), en wordt gehoord als hartgeruis of vaatgeruis. Het getal van Reynolds voorspelt wanneer stroming turbulent wordt. Turbulentie beschadigt het endotheel en bevordert atherosclerose.</p>","image_url":"","wiki_title":"Turbulence","match":"turbulente flow|turbulente stroming|turbulentie","option_only":true},"een myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"een myocardinfarct","option_only":true},"doorgemaakt mi":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"doorgemaakt mi","option_only":true},"myocardinfarcering":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarcering","option_only":true},"lis-diureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"lis-diureticum","option_only":true},"een lisdiureticum":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"een lisdiureticum","option_only":true},"een thiazidediureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"een thiazidediureticum","option_only":true},"open ductus botalli":{"title":"Persisterende ductus arteriosus (PDA)","short":"Bij een PDA sluit de ductus arteriosus na de geboorte niet, waardoor bloed van de aorta naar de a. pulmonalis stroomt.","definition":"<p>De <strong>ductus arteriosus</strong> verbindt foetaal de a. pulmonalis met de aorta. Normaal sluit hij in de eerste dagen na de geboorte (door stijgende zuurstofspanning en dalende prostaglandinen). Bij prematuren en na rubella in de zwangerschap blijft hij vaker open. Er is een continu ‘machinegeruis’; sluiting met indomethacine/ibuprofen of via een katheter.</p>","image_url":"","wiki_title":"Patent ductus arteriosus","match":"open ductus botalli","option_only":true},"tromboembolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"tromboembolie","option_only":true},"trombo-embolie":{"title":"Longembolie","short":"Bij een longembolie sluit een stolsel (meestal uit de beenvenen) een longslagader af, met acute benauwdheid en pijn bij het ademen.","definition":"<p>Een <strong>longembolie</strong> ontstaat meestal door een trombus uit de diepe venen van been of bekken. Risicofactoren volgen de trias van Virchow: stase (immobilisatie), hypercoagulabiliteit (kanker, oestrogenen, zwangerschap, erfelijke trombofilie) en vaatwandschade (operatie, trauma). Klachten: plotselinge dyspneu, pleuritische pijn, tachycardie, soms hemoptoë of collaps. Diagnostiek met een beslisregel, D-dimeer en CT-angiografie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Pulmonary embolism","match":"trombo-embolie","option_only":true},"glomerulaire filtratiesnelheid":{"title":"Nier","short":"De nieren filteren het bloed en regelen water-, zout- en zuur-base-evenwicht en bloeddruk; ook maken ze hormonen (renine, EPO, actief vitamine D).","definition":"<p>De <strong>nieren</strong> liggen retroperitoneaal aan weerszijden van de wervelkolom. De functionele eenheid is het <em>nefron</em>: glomerulus, proximale tubulus, lis van Henle, distale tubulus en verzamelbuis. Samen filteren de nieren ongeveer 180 liter per dag, waarvan meer dan 99% wordt teruggeresorbeerd.</p><p>Ze scheiden afvalstoffen (ureum, creatinine) en geneesmiddelen uit, regelen het volume en de samenstelling van de lichaamsvloeistoffen en de pH, en maken <em>renine</em> (bloeddruk), <em>erytropoëtine</em> (aanmaak van rode bloedcellen) en <em>calcitriol</em> (actief vitamine D).</p>","image_url":"","wiki_title":"Kidney","match":"glomerulaire filtratiesnelheid","option_only":true},"ernstige sepsis":{"title":"Sepsis","short":"Sepsis is een levensbedreigende orgaandisfunctie door een ontregelde afweerreactie op een infectie.","definition":"<p>Bij <strong>sepsis</strong> leidt de reactie van het lichaam op een infectie tot schade aan de eigen organen: hypotensie, verwardheid, snelle ademhaling, nierfalen, stollingsstoornissen en een verhoogd lactaat. Septische shock is sepsis met hypotensie die vasopressoren vereist. Snelle herkenning (bijv. qSOFA), bloedkweken, antibiotica binnen een uur en vochtresuscitatie zijn essentieel.</p>","image_url":"","wiki_title":"Sepsis","match":"ernstige sepsis","option_only":true},"pleuritis":{"title":"Pleuritis","short":"Pleuritis is een ontsteking van de longvliezen, met scherpe pijn bij ademen en soms pleurawrijven.","definition":"<p><strong>Pleuritis</strong> ontstaat o.a. bij virale infecties, pneumonie, longembolie, auto-immuunziekten (SLE, RA) en maligniteit. De pijn neemt toe bij diep inademen en hoesten. Er kan pleuravocht ontstaan.</p>","image_url":"","wiki_title":"Pleurisy","match":"pleuritis","option_only":true},"ventrikelfibrilleren (vf)":{"title":"Ventrikelfibrilleren","short":"Ventrikelfibrilleren is een chaotische elektrische activiteit van de kamers zonder effectieve pompfunctie: een circulatiestilstand.","definition":"<p>Bij <strong>ventrikelfibrilleren</strong> pompt het hart geen bloed meer; binnen seconden treedt bewusteloosheid op. Het ontstaat vaak bij acute ischemie, een oud infarctlitteken, cardiomyopathie of elektrolytstoornissen. De behandeling is direct reanimeren en zo snel mogelijk defibrilleren (AED).</p>","image_url":"","wiki_title":"Ventricular fibrillation","match":"ventrikelfibrilleren (vf)","option_only":true},"type 2 diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"type 2 diabetes mellitus","option_only":true},"a. mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"a. mesenterica superior|arteria mesenterica superior","option_only":true},"arteria mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"arteria mesenterica superior","option_only":true},"a. carotis communis":{"title":"A. carotis communis","short":"De a. carotis communis loopt in de hals omhoog en splitst ter hoogte van het schildkraakbeen in de a. carotis interna en externa.","definition":"<p>Rechts komt de <strong>a. carotis communis</strong> uit de truncus brachiocephalicus, links rechtstreeks uit de aortaboog. Bij de splitsing liggen de sinus caroticus (baroreceptoren) en het glomus caroticum (chemoreceptoren). De carotispols is lateraal van het strottenhoofd voelbaar.</p>","image_url":"","wiki_title":"Common carotid artery","match":"a. carotis communis|arteria carotis communis|a.carotis|halsslagader","option_only":true},"arteria hepatica communis":{"title":"A. hepatica communis","short":"De a. hepatica communis is een tak van de truncus coeliacus die de lever, galblaas en delen van maag en duodenum voorziet.","definition":"<p>De <strong>a. hepatica communis</strong> geeft de a. gastroduodenalis af en loopt verder als a. hepatica propria in het lig. hepatoduodenale, samen met de v. portae en de ductus choledochus. De a. gastroduodenalis ligt achter het duodenum en kan bloeden bij een ulcus aan de achterwand.</p>","image_url":"","wiki_title":"Common hepatic artery","match":"arteria hepatica communis|a. hepatica communis","option_only":true},"arteria splenica dextra":{"title":"A. splenica (lienalis)","short":"De a. splenica is de grootste tak van de truncus coeliacus; ze loopt kronkelend langs de bovenrand van de pancreas naar de milt.","definition":"<p>De <strong>a. splenica</strong> voorziet de milt, het grootste deel van de pancreas (corpus en staart) en via de aa. gastricae breves en a. gastro-omentalis sinistra een deel van de maag. Er bestaat geen ‘a. splenica dextra’; de milt ligt links.</p>","image_url":"","wiki_title":"Splenic artery","match":"arteria splenica dextra|a. splenica|a. lienalis|miltslagader","option_only":true},"isovolumetrische contractiefase":{"title":"Isovolumetrische contractiefase","short":"In de isovolumetrische contractiefase trekt de ventrikel samen terwijl alle kleppen gesloten zijn: de druk stijgt snel, het volume blijft gelijk.","definition":"<p>Pas als de ventrikeldruk de druk in aorta of a. pulmonalis overstijgt, gaan de semilunaire kleppen open en volgt de ejectiefase.</p>","image_url":"","wiki_title":"Isovolumetric contraction","match":"isovolumetrische contractiefase|isovolumetrische contractie","option_only":true},"pulmonalisklep":{"title":"Pulmonalisklep","short":"De pulmonalisklep ligt tussen de rechterventrikel en de longslagader en heeft drie halvemaanvormige slippen.","definition":"<p>De <strong>pulmonalisklep</strong> sluit aan het begin van de diastole (P2-component van de tweede harttoon). Bij inademing sluit hij iets later, wat een fysiologische splijting van de tweede toon geeft. Aandoeningen zijn pulmonalisstenose (vaak aangeboren) en pulmonalisinsufficiëntie (bijv. na Fallot-correctie of bij pulmonale hypertensie).</p>","image_url":"","wiki_title":"Pulmonary valve","match":"pulmonalisklep|pulmonaalklep","option_only":true},"tricuspidalisklep":{"title":"Tricuspidalisklep","short":"De tricuspidalisklep ligt tussen het rechteratrium en de rechterventrikel en heeft drie slippen.","definition":"<p>Insufficiëntie van de <strong>tricuspidalisklep</strong> komt vaak secundair voor bij verwijding van de rechterventrikel (pulmonale hypertensie, linkszijdig hartfalen). Endocarditis van de tricuspidalisklep komt vooral voor bij intraveneus drugsgebruik. Ebstein-anomalie is een aangeboren afwijking van deze klep.</p>","image_url":"","wiki_title":"Tricuspid valve","match":"tricuspidalisklep","option_only":true},"aortaklep":{"title":"Aortaklep","short":"De aortaklep ligt tussen de linkerventrikel en de aorta en heeft normaal drie halvemaanvormige slippen.","definition":"<p>Vlak boven de <strong>aortaklep</strong> ontspringen de kransslagaders. Bij ongeveer 1–2% van de mensen is de klep bicuspide, wat eerder tot stenose of insufficiëntie leidt en samengaat met verwijding van de aorta ascendens.</p>","image_url":"","wiki_title":"Aortic valve","match":"aortaklep","option_only":true},"vasopressineblokker":{"title":"Vasopressinereceptorantagonist (tolvaptan)","short":"Tolvaptan blokkeert de V2-receptor in de verzamelbuis, waardoor vrij water wordt uitgescheiden.","definition":"<p><strong>Vaptanen</strong> worden gebruikt bij hyponatriëmie door SIADH en, in de vorm van tolvaptan, om de groei van cysten bij autosomaal dominante polycysteuze nierziekte te remmen. De natriumspiegel moet goed worden gecontroleerd, omdat te snelle correctie gevaarlijk is; ook leverschade komt voor.</p>","image_url":"","wiki_title":"Tolvaptan","match":"vasopressineblokker|tolvaptan|vaptanen|auquaporine-2-blokker","option_only":true},"hypalbuminaemie":{"title":"Hypoalbuminemie","short":"Hypoalbuminemie is een te laag albumine in het bloed, met oedeem als belangrijk gevolg.","definition":"<p>Oorzaken van <strong>hypoalbuminemie</strong> zijn verlies (nefrotisch syndroom, eiwitverliezende enteropathie, brandwonden), verminderde aanmaak (leverziekte, ondervoeding) en ontsteking (negatief acutefase-eiwit). Het totaal calcium daalt mee; het geïoniseerde calcium is dan vaak normaal.</p>","image_url":"","wiki_title":"Hypoalbuminemia","match":"hypalbuminaemie|hypoalbuminemie|laag albumine","option_only":true},"malaat":{"title":"Malaat","short":"Malaat is een tussenproduct van de citroenzuurcyclus en speelt een rol in de malaat-aspartaatshuttle en de gluconeogenese.","definition":"<p>In de citroenzuurcyclus wordt fumaraat omgezet in <strong>malaat</strong> en daarna (met vorming van NADH) in oxaalacetaat. Via de malaat-aspartaatshuttle worden reductie-equivalenten uit het cytosol het mitochondrion in gebracht; malaat vervoert bij de gluconeogenese ook oxaalacetaat het mitochondrion uit.</p>","image_url":"","wiki_title":"Malic acid","match":"malaat|appelzuur","option_only":true},"vasoconstrictie":{"title":"Vasoconstrictie","short":"Vasoconstrictie is vernauwing van bloedvaten door samentrekking van de gladde spier in de vaatwand.","definition":"<p><strong>Vasoconstrictie</strong> wordt veroorzaakt door o.a. sympathische activatie (α1), angiotensine II, endotheline, vasopressine en kou. Het verhoogt de bloeddruk en stuurt bloed naar vitale organen, bijvoorbeeld bij bloedverlies. In de long trekken vaten juist samen bij hypoxie.</p>","image_url":"","wiki_title":"Vasoconstriction","match":"vasoconstrictie|vaatvernauwing|perifere vasoconstrictie","option_only":true},"hyperkaliumie":{"title":"Hyperkaliëmie","short":"Hyperkaliëmie is een te hoog kalium in het bloed; gevaarlijk door het risico op hartritmestoornissen.","definition":"<p><strong>Hyperkaliëmie</strong> ontstaat door verminderde uitscheiding (nierfalen, ACE-remmers, ARB's, kaliumsparende diuretica, hypoaldosteronisme), verschuiving uit de cel (acidose, insulinetekort, celafbraak) of overmatige inname. Op het ECG ziet men spitse T-toppen, verbrede QRS-complexen en uiteindelijk ventrikelfibrilleren. Acute behandeling: calciumgluconaat (membraanstabilisatie), insuline met glucose en salbutamol, en kalium verwijderen.</p>","image_url":"","wiki_title":"Hyperkalemia","match":"hyperkaliumie","option_only":true},"tetralogie van fallot":{"title":"Tetralogie van Fallot","short":"De tetralogie van Fallot is de meest voorkomende cyanotische aangeboren hartafwijking: VSD, overrijdende aorta, pulmonalisstenose en rechterventrikelhypertrofie.","definition":"<p>Bij <strong>Fallot</strong> stroomt zuurstofarm bloed via het VSD naar de aorta (rechts-linksshunt). Kenmerkend zijn ‘tet spells’ die verbeteren bij hurken en een laarsvormig hart op de X-thorax. Chirurgische correctie gebeurt meestal in het eerste levensjaar.</p>","image_url":"","wiki_title":"Tetralogy of Fallot","match":"tetralogie van fallot|fallot","option_only":true},"selectiebias":{"title":"Selectiebias","short":"Selectiebias ontstaat als de manier waarop deelnemers in een onderzoek terechtkomen samenhangt met zowel blootstelling als uitkomst.","definition":"<p>Voorbeelden van <strong>selectiebias</strong> zijn het gebruik van ziekenhuiscontroles in een patiënt-controleonderzoek, selectieve uitval tijdens follow-up en het ‘healthy worker effect’. Anders dan confounding kan selectiebias achteraf niet worden gecorrigeerd.</p>","image_url":"","wiki_title":"Selection bias","match":"selectiebias|selectievertekening","option_only":true},"n. laryngeus recurrens":{"title":"N. laryngeus recurrens","short":"De n. laryngeus recurrens is een tak van de n. vagus die vrijwel alle stembandspieren innerveert; links loopt hij om de aortaboog, rechts om de a. subclavia.","definition":"<p>Door zijn lange verloop is de <strong>n. laryngeus recurrens</strong> kwetsbaar bij schildklier-, slokdarm- en thoraxchirurgie en bij tumoren van long, slokdarm, schildklier en mediastinum, en (links) bij een aneurysma van de aortaboog. Uitval geeft heesheid door een stembandparese.</p>","image_url":"","wiki_title":"Recurrent laryngeal nerve","match":"n. laryngeus recurrens|nervus laryngeus recurrens","option_only":true},"a. renalis":{"title":"A. renalis (nierslagader)","short":"De aa. renales ontspringen ter hoogte van L1–L2 uit de aorta en voorzien de nieren; de rechter loopt achter de v. cava inferior.","definition":"<p>Een <strong>nierarteriestenose</strong> (atherosclerose bij ouderen, fibromusculaire dysplasie bij jonge vrouwen) activeert het RAAS en geeft hypertensie, soms met een vaatgeruis in de buik. Bij dubbelzijdige stenose kunnen ACE-remmers een acute nierfunctiedaling geven.</p>","image_url":"","wiki_title":"Renal artery","match":"a. renalis|a.renalis|arteria renalis|nierslagader","option_only":true},"vldl":{"title":"VLDL","short":"VLDL is een triglyceriderijk lipoproteïne dat door de lever wordt gemaakt en vetten naar de weefsels vervoert.","definition":"<p>Na afgifte van triglyceriden via lipoproteïnelipase wordt <strong>VLDL</strong> omgezet in IDL en vervolgens LDL. Verhoogde VLDL-productie (bij obesitas, insulineresistentie, alcohol) geeft hypertriglyceridemie.</p>","image_url":"","wiki_title":"Very-low-density lipoprotein","match":"vldl|very low density lipoprotein","option_only":true},"hydronefrose":{"title":"Hydronefrose","short":"Hydronefrose is een verwijding van nierbekken en -kelken door een belemmerde urineafvloed.","definition":"<p>Oorzaken van <strong>hydronefrose</strong> zijn o.a. een ureter- of blaassteen, een pyelo-ureterale overgangsstenose (aangeboren), prostaatvergroting, tumoren in het bekken en zwangerschap. Langdurige obstructie beschadigt de nier; een geïnfecteerde gestuwde nier is een urologisch spoedgeval.</p>","image_url":"","wiki_title":"Hydronephrosis","match":"hydronefrose|hydronephrose|nierstuwing","option_only":true},"vasa recta":{"title":"Vasa recta","short":"De vasa recta zijn lange, haarspeldvormige capillairen in het niermerg, die het tegenstroommechanisme in stand houden.","definition":"<p>De <strong>vasa recta</strong> lopen evenwijdig aan de lissen van Henle. Door hun trage doorstroming en haarspeldvorm voeren ze zuurstof en voedingsstoffen aan zonder de osmotische gradiënt in het merg weg te spoelen.</p>","image_url":"","wiki_title":"Vasa recta (kidney)","match":"vasa recta","option_only":true},"preload":{"title":"Preload (voorbelasting)","short":"Preload is de vulling of rek van de ventrikel aan het eind van de diastole; volgens Frank-Starling verhoogt meer vulling het slagvolume.","definition":"<p>De <strong>preload</strong> hangt af van het veneuze terugstroom en het circulerend volume. Diuretica en nitraten verlagen de preload; vulling verhoogt hem. Bij een ondervuld hart stijgt het slagvolume na vochttoediening.</p>","image_url":"","wiki_title":"Preload (cardiology)","match":"preload|voorbelasting","option_only":true},"afterload":{"title":"Afterload (nabelasting)","short":"Afterload is de weerstand waartegen de ventrikel bloed moet uitpompen, vooral bepaald door de arteriële bloeddruk en de aortaklep.","definition":"<p>Een verhoogde <strong>afterload</strong> (hypertensie, aortastenose) leidt tot concentrische hypertrofie. Vaatverwijders (ACE-remmers, hydralazine) verlagen de afterload en verbeteren zo de pompfunctie bij hartfalen.</p>","image_url":"","wiki_title":"Afterload","match":"afterload|nabelasting","option_only":true},"arterioveneuze fistels":{"title":"Arterioveneuze fistel","short":"Een arterioveneuze fistel is een directe verbinding tussen een slagader en een ader, zonder capillairbed.","definition":"<p>Een <strong>AV-fistel</strong> kan aangeboren zijn (malformatie), door trauma ontstaan of chirurgisch worden aangelegd als toegang voor hemodialyse. Grote shunts kunnen high-output hartfalen geven. Arterioveneuze malformaties in het brein kunnen bloeden of epilepsie veroorzaken.</p>","image_url":"","wiki_title":"Arteriovenous fistula","match":"arterioveneuze fistels|arterioveneuze fistel|av-fistel|arterioveneuze anastomosen|arterioveneuze malformatie","option_only":true},"amiloride":{"title":"Amiloride","short":"Amiloride is een kaliumsparend diureticum dat de natriumkanalen (ENaC) in de verzamelbuis blokkeert.","definition":"<p><strong>Amiloride</strong> wordt vaak gecombineerd met een thiazide of lisdiureticum om kaliumverlies te beperken. Het wordt ook gebruikt bij lithium-geïnduceerde nefrogene diabetes insipidus en het syndroom van Liddle. Bijwerking: hyperkaliëmie.</p>","image_url":"","wiki_title":"Amiloride","match":"amiloride|triamtereen|kaliumsparend diureticum","option_only":true},"acuut coronair syndroom":{"title":"Acuut coronair syndroom (ACS)","short":"Het acuut coronair syndroom omvat instabiele angina pectoris, NSTEMI en STEMI, alle door een acute verstoring van de kransslagaderdoorbloeding.","definition":"<p>Bij <strong>ACS</strong> scheurt meestal een atherosclerotische plaque, gevolgd door trombose. Onderscheid op basis van ECG (ST-elevatie of niet) en troponine (wel of geen myocardschade). Behandeling: plaatjesremmers, antistolling en, afhankelijk van het type, spoed- of vroege PCI.</p>","image_url":"","wiki_title":"Acute coronary syndrome","match":"acuut coronair syndroom|acs","option_only":true},"hyperventilatie":{"title":"Hyperventilatie","short":"Bij hyperventilatie wordt meer geademd dan nodig is, waardoor het CO₂ daalt (respiratoire alkalose) met tintelingen en duizeligheid.","definition":"<p>Een <strong>hyperventilatieaanval</strong> kan worden uitgelokt door angst of paniek en geeft tintelingen rond de mond en in de vingers, duizeligheid, benauwdheid en soms carpopedale spasmen. Hyperventilatie kan ook compensatoir zijn (metabole acidose) of door hypoxie, pijn of koorts ontstaan; die oorzaken moeten worden uitgesloten.</p>","image_url":"","wiki_title":"Hyperventilation","match":"hyperventilatie|chronisch hyperventileren","option_only":true},"acuut myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"acuut myocardinfarct","option_only":true},"lekkende mitralisklep":{"title":"Mitralisinsufficiëntie","short":"Bij mitralisinsufficiëntie sluit de mitralisklep onvoldoende, waardoor bloed in de systole terugstroomt naar het linkeratrium.","definition":"<p><strong>Mitralisinsufficiëntie</strong> kan primair zijn (klepprolaps, endocarditis, reumatische klepziekte) of secundair aan verwijding of ischemie van de linkerventrikel. Het linkeratrium raakt overbelast, met risico op boezemfibrilleren en longstuwing. Bij auscultatie hoort men een holosystolisch geruis aan de apex, uitstralend naar de oksel.</p>","image_url":"","wiki_title":"Mitral insufficiency","match":"lekkende mitralisklep","option_only":true},"conventionele x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"conventionele x-thorax","option_only":true},"a. lienalis":{"title":"A. splenica (lienalis)","short":"De a. splenica is de grootste tak van de truncus coeliacus; ze loopt kronkelend langs de bovenrand van de pancreas naar de milt.","definition":"<p>De <strong>a. splenica</strong> voorziet de milt, het grootste deel van de pancreas (corpus en staart) en via de aa. gastricae breves en a. gastro-omentalis sinistra een deel van de maag. Er bestaat geen ‘a. splenica dextra’; de milt ligt links.</p>","image_url":"","wiki_title":"Splenic artery","match":"a. lienalis","option_only":true},"refluxoesofagitis":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"refluxoesofagitis","option_only":true},"a. hepatica communis":{"title":"A. hepatica communis","short":"De a. hepatica communis is een tak van de truncus coeliacus die de lever, galblaas en delen van maag en duodenum voorziet.","definition":"<p>De <strong>a. hepatica communis</strong> geeft de a. gastroduodenalis af en loopt verder als a. hepatica propria in het lig. hepatoduodenale, samen met de v. portae en de ductus choledochus. De a. gastroduodenalis ligt achter het duodenum en kan bloeden bij een ulcus aan de achterwand.</p>","image_url":"","wiki_title":"Common hepatic artery","match":"a. hepatica communis","option_only":true},"gefenestreerde capillairen":{"title":"Gefenestreerde capillairen met diafragma","short":"Dit zijn capillairen met porieën in het endotheel die afgesloten zijn door een dun diafragma; ze komen o.a. voor in endocriene klieren en de darm.","definition":"<p>In <strong>gefenestreerde capillairen</strong> bevat het endotheel kleine openingen (fenestrae) van ongeveer 60–80 nm. Bij het type <em>met diafragma</em> worden deze afgedekt door een dun eiwitvlies. Ze laten snelle uitwisseling van kleine moleculen toe en komen voor in endocriene klieren, darmvlokken en de plexus choroideus.</p>","image_url":"","wiki_title":"Capillary","match":"gefenestreerde capillairen","option_only":true},"discontinue capillair":{"title":"Discontinue (sinusoïdale) capillairen","short":"Sinusoïden zijn wijde capillairen met grote openingen tussen de endotheelcellen en een onvolledige basaalmembraan, o.a. in lever, milt en beenmerg.","definition":"<p>In <strong>sinusoïdale capillairen</strong> kunnen grote moleculen en soms cellen de vaatwand passeren. In de lever liggen ze tussen de balkjes hepatocyten; daar zit tussen endotheel en hepatocyten de ruimte van Disse. In milt en beenmerg laten ze bloedcellen door.</p>","image_url":"","wiki_title":"Capillary","match":"discontinue capillair","option_only":true},"sinusoïdaal endotheel":{"title":"Sinusoïdale endotheelcel","short":"Sinusoïdale endotheelcellen bekleden de leversinusoïden en hebben open poriën zonder echte basaalmembraan.","definition":"<p><strong>Lever-sinusoïdale endotheelcellen</strong> bevatten groepjes fenestrae (zeefplaten) waardoor plasma vrij de ruimte van Disse in kan stromen, in contact met de microvilli van hepatocyten. Ze ruimen ook kleine deeltjes uit het bloed op. Bij fibrose verdwijnen de fenestrae (capillarisatie).</p>","image_url":"","wiki_title":"Liver sinusoidal endothelial cell","match":"sinusoïdaal endotheel","option_only":true},"endocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"endocriene pancreas","option_only":true},"exocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"exocriene pancreas","option_only":true},"abdominaal aneurysma aortae":{"title":"Aneurysma van de aorta abdominalis (AAA)","short":"Een AAA is een verwijding van de buikslagader tot meer dan 3 cm; bij ruptuur is het levensbedreigend.","definition":"<p>Een <strong>AAA</strong> komt vooral voor bij oudere mannen die roken, met hypertensie en familiaire belasting. Meestal geeft het geen klachten; soms voelt men een pulserende zwelling. Een ruptuur geeft plotseling buik- of rugpijn en shock. Electieve behandeling (open of endovasculair) vanaf ongeveer 5,5 cm bij mannen.</p>","image_url":"","wiki_title":"Abdominal aortic aneurysm","match":"abdominaal aneurysma aortae","option_only":true},"hypertrofie van het hart":{"title":"Linkerventrikelhypertrofie","short":"Linkerventrikelhypertrofie is een verdikking van de wand van de linkerkamer, meestal door langdurige drukbelasting.","definition":"<p><strong>LVH</strong> ontstaat bij hypertensie, aortaklepstenose, HCM en training (sporthart). Ze geeft diastolische disfunctie en is een sterke risicofactor voor hartfalen, ritmestoornissen en plotse dood. Zichtbaar op ECG (verhoogde voltages) en echo.</p>","image_url":"","wiki_title":"Left ventricular hypertrophy","match":"hypertrofie van het hart","option_only":true},"'fatty streaks'":{"title":"Fatty streaks","short":"Fatty streaks zijn de vroegste zichtbare afwijkingen van atherosclerose: gele strepen in de vaatwand door schuimcellen.","definition":"<p><strong>Fatty streaks</strong> bestaan uit opeenhopingen van met lipiden gevulde macrofagen (schuimcellen) in de intima. Ze komen al bij kinderen voor en kunnen uitgroeien tot fibreuze plaques.</p>","image_url":"","wiki_title":"Fatty streak","match":"'fatty streaks'|fatty streaks|fatty streak","option_only":true},"allantoïs":{"title":"Allantoïs","short":"De allantoïs is een embryonale uitstulping van de achterdarm naar de navelstreng; ze wordt later de urachus.","definition":"<p>De <strong>allantoïs</strong> is bij de mens klein, maar de vaten in haar wand worden de navelvaten. Haar restant, de urachus, verbindt de blaas met de navel en verbindweefselt normaal.</p>","image_url":"","wiki_title":"Allantois","match":"allantoïs|allantois","option_only":true},"mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"mesenterica superior","option_only":true},"hdl":{"title":"HDL-cholesterol","short":"HDL vervoert cholesterol uit de weefsels terug naar de lever (reverse cholesterol transport); een hoog HDL hangt samen met minder hart- en vaatziekten.","definition":"<p>Een laag <strong>HDL</strong> komt voor bij roken, overgewicht, weinig beweging, diabetes type 2 en hypertriglyceridemie. Medicijnen die alleen het HDL verhogen, verminderen het risico op hart- en vaatziekten niet.</p>","image_url":"","wiki_title":"High-density lipoprotein","match":"hdl|high density lipoproteins|hdl-cholesterol","option_only":true},"high density lipoprotein (hdl) cholesterol":{"title":"HDL","short":"High-density lipoprotein; voert cholesterol vanuit perifere weefsels terug naar de lever (‘goede cholesterol’).","definition":"<p><b>HDL</b> verzorgt het omgekeerde cholesteroltransport: opname uit o.a. de vaatwand en terugvoer naar de lever.</p>","image_url":"","wiki_title":"High-density lipoprotein","match":"high density lipoprotein (hdl) cholesterol","option_only":true},"carbamoylfosfaat (cpsi)":{"title":"Carbamoylfosfaat","short":"Carbamoylfosfaat is een molecuul dat de eerste NH2-groep in de ureumcyclus levert; het wordt gevormd uit ammoniak en CO2.","definition":"<p><b>Carbamoylfosfaat</b> is het startproduct van de ureumcyclus. Het levert het eerste stikstofatoom van ureum; het tweede komt van aspartaat.</p>","image_url":"","wiki_title":"Carbamoyl phosphate","match":"carbamoylfosfaat (cpsi)","option_only":true},"blocking behavior":{"title":"Blocking behavior","short":"Gespreksgedrag van de arts dat het uiten van emoties door de patiënt afremt of blokkeert, bijvoorbeeld door in feiten te vluchten.","definition":"<p><strong>Blocking behavior</strong> omvat (vaak onbewuste) gesprekstechnieken waarmee een hulpverlener het uiten van emoties door de patiënt tegenhoudt. Voorbeelden van valkuilen zijn 'vluchten in feiten', te snelle geruststelling, willen oplossen en te snelle identificatie.</p>","image_url":"","wiki_title":"","match":"blocking behavior","option_only":true},"behandeling met een carboanhydraseremmer":{"title":"Carboanhydraseremmer (acetazolamide)","short":"Carboanhydraseremmers zoals acetazolamide remmen de terugresorptie van bicarbonaat in de proximale tubulus.","definition":"<p><strong>Acetazolamide</strong> geeft een zwakke diurese met verlies van bicarbonaat (metabole acidose) en kalium. Het wordt gebruikt bij glaucoom (minder kamerwaterproductie), hoogteziekte, idiopathische intracraniële hypertensie en soms metabole alkalose.</p>","image_url":"","wiki_title":"Acetazolamide","match":"behandeling met een carboanhydraseremmer","option_only":true},"nervus laryngeus recurrens":{"title":"N. laryngeus recurrens","short":"De n. laryngeus recurrens is een tak van de n. vagus die vrijwel alle stembandspieren innerveert; links loopt hij om de aortaboog, rechts om de a. subclavia.","definition":"<p>Door zijn lange verloop is de <strong>n. laryngeus recurrens</strong> kwetsbaar bij schildklier-, slokdarm- en thoraxchirurgie en bij tumoren van long, slokdarm, schildklier en mediastinum, en (links) bij een aneurysma van de aortaboog. Uitval geeft heesheid door een stembandparese.</p>","image_url":"","wiki_title":"Recurrent laryngeal nerve","match":"nervus laryngeus recurrens","option_only":true},"arteriolen (diameter <500 micron)":{"title":"Arteriolen","short":"Arteriolen zijn de kleinste arteriën met een spierwand; ze bepalen het grootste deel van de perifere vaatweerstand.","definition":"<p>In <strong>arteriolen</strong> daalt de bloeddruk het sterkst. Door samen te trekken of te verwijden regelen ze de doorbloeding van weefsels (autoregulatie, sympathische invloed, lokale metabolieten) en daarmee de bloeddruk. Bij langdurige hypertensie of diabetes ontstaat arteriolosclerose (hyaliene verdikking).</p>","image_url":"","wiki_title":"Arteriole","match":"arteriolen (diameter <500 micron)","option_only":true},"very low density lipoprotein (vldl)":{"title":"VLDL","short":"VLDL is een triglyceriderijk lipoproteïne dat door de lever wordt gemaakt en vetten naar de weefsels vervoert.","definition":"<p>Na afgifte van triglyceriden via lipoproteïnelipase wordt <strong>VLDL</strong> omgezet in IDL en vervolgens LDL. Verhoogde VLDL-productie (bij obesitas, insulineresistentie, alcohol) geeft hypertriglyceridemie.</p>","image_url":"","wiki_title":"Very-low-density lipoprotein","match":"very low density lipoprotein (vldl)","option_only":true},"acidose":{"title":"Acidose","short":"Een verlaagde pH van het bloed (te zuur milieu). Metabole acidose gaat vaak samen met hyperkaliëmie.","definition":"<p><b>Acidose</b> is een verstoring van het zuur-base-evenwicht met een pH < 7,35. Bij metabole acidose zijn HCO3⁻ en base excess verlaagd. Acidose verschuift kalium uit de cellen en verergert daarmee hyperkaliëmie; correctie van de acidose corrigeert mede de hyperkaliëmie.</p>","image_url":"","wiki_title":"Acidosis","match":"acidose","option_only":true},"glomerulaire endotheelcellen":{"title":"Glomerulaire endotheelcellen","short":"De gefenestreerde endotheelcellen van de glomerulaire capillairen vormen de eerste laag van de filtratiebarrière.","definition":"<p>De <b>glomerulaire endotheelcellen</b> zijn sterk gefenestreerd en houden samen met de basaalmembraan en podocyten cellen en grote eiwitten tegen tijdens filtratie.</p>","image_url":"","wiki_title":"Glomerulus (kidney)","match":"glomerulaire endotheelcellen","option_only":true},"aspartaat":{"title":"Aspartaat","short":"Aspartaat is een aminozuur dat in de ureumcyclus de tweede NH2-groep van ureum levert.","definition":"<p><b>Aspartaat</b> is een aminozuur dat in de ureumcyclus condenseert met citrulline tot argininosuccinaat en zo de tweede stikstof voor ureum aanlevert.</p>","image_url":"","wiki_title":"Aspartic acid","match":"aspartaat","option_only":true},"carnitinefosfaat (cpt1)":{"title":"CPT1","short":"Carnitine-palmitoyltransferase 1; transporteert vetzuren het mitochondrion in en wordt geremd door malonyl-CoA.","definition":"<p><b>CPT1</b> is de snelheidsbepalende stap voor vetzuuropname in het mitochondrion voor de β-oxidatie.</p>","image_url":"","wiki_title":"Carnitine palmitoyltransferase I","match":"carnitinefosfaat (cpt1)","option_only":true},"tunica media":{"title":"Tunica media","short":"De tunica media is de middelste vaatwandlaag met glad spierweefsel en elastische vezels; in elastische arteriën is deze laag het meest prominent.","definition":"<p>De <b>tunica media</b> is de middelste laag van de vaatwand. Bij elastische arteriën (zoals de aorta) bevat zij veel elastische lamellen en is zij het dikst.</p>","image_url":"","wiki_title":"Tunica media","match":"tunica media","option_only":true},"verlaagde spiegel van antidiuretisch hormoon (adh)":{"title":"ADH (vasopressine)","short":"Antidiuretisch hormoon dat de waterterugresorptie in de nier verhoogt via aquaporinen; stijgt bij hyperosmolaliteit en hypovolemie.","definition":"<p><b>ADH (vasopressine)</b> verhoogt de permeabiliteit voor water in de verzamelbuizen (via <b>aquaporinen</b>), waardoor meer water wordt teruggeresorbeerd. Het stijgt 'appropriately' bij hyperosmolaliteit en hypovolemie.</p>","image_url":"","wiki_title":"Vasopressin","match":"verlaagde spiegel van antidiuretisch hormoon (adh)","option_only":true},"lanosterol":{"title":"Lanosterol","short":"Lanosterol is een sterol-intermediair in de cholesterolsynthese, gevormd na cyclisatie van squaleen.","definition":"<p><b>Lanosterol</b> is het eerste sterol in de cholesterolbiosynthese, dat via meerdere stappen wordt omgezet in cholesterol.</p>","image_url":"","wiki_title":"Lanosterol","match":"lanosterol","option_only":true},"persisterende truncus arteriosus":{"title":"Persisterende truncus arteriosus","short":"Aangeboren afwijking waarbij één gemeenschappelijk vat uit het hart ontspringt in plaats van gescheiden aorta en a. pulmonalis.","definition":"<p>Bij een <b>persisterende truncus arteriosus</b> is het embryonale truncusseptum niet gevormd, zodat één vat long- en lichaamscirculatie voedt.</p>","image_url":"","wiki_title":"Persistent truncus arteriosus","match":"persisterende truncus arteriosus","option_only":true},"antrum pyloricum":{"title":"Antrum pyloricum","short":"Het distale, trechtervormige deel van de maag dat overgaat in de pylorus.","definition":"<p>Het <b>antrum pyloricum</b> is het onderste deel van de maag, tussen het corpus en de pylorus. Hier bevinden zich G-cellen die gastrine produceren; het antrum maalt en stuwt de voedselbrij richting duodenum.</p>","image_url":"","wiki_title":"Pylorus","match":"antrum pyloricum","option_only":true},"monocyten":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyten","option_only":true},"crista terminalis":{"title":"Crista terminalis","short":"Spierrichel in het rechter atrium die het gladwandige deel scheidt van het deel met mm. pectinati.","definition":"<p>De <b>crista terminalis</b> markeert de embryonale grens tussen sinus venosus en het eigenlijke atrium.</p>","image_url":"","wiki_title":"Crista terminalis","match":"crista terminalis","option_only":true},"calix major":{"title":"Calix major","short":"Grote nierkelk waarin meerdere kleine kelken samenkomen en die uitmondt in het nierbekken.","definition":"<p>De <b>calices majores</b> verzamelen urine uit de calices minores en leiden deze naar de pelvis renalis.</p>","image_url":"","wiki_title":"Renal calyx","match":"calix major","option_only":true},"cortex renalis":{"title":"Cortex renalis","short":"Buitenste laag van de nier met de glomeruli en de proximale en distale tubuli.","definition":"<p>De <b>cortex renalis</b> bevat de nierlichaampjes (glomeruli) en het grootste deel van de tubulaire structuren.</p>","image_url":"","wiki_title":"Renal cortex","match":"cortex renalis","option_only":true},"v. azygos":{"title":"V. azygos","short":"Ongepaarde ader die het bloed uit de intercostale venen naar de v. cava superior afvoert.","definition":"<p>De <b>v. azygos</b> loopt langs de rechterzijde van de wervelkolom en mondt uit in de vena cava superior.</p>","image_url":"","wiki_title":"Azygos vein","match":"v. azygos","option_only":true},"calix minor":{"title":"Calix minor","short":"Een kleine nierkelk die de urine opvangt van een enkele nierpapil en afgeeft aan een calix major.","definition":"<p>De <b>calices minores</b> zijn trechtervormige structuren die de urine van de papillen van de nierpiramiden opvangen. Meerdere calices minores komen samen in een calix major.</p>","image_url":"","wiki_title":"Minor calyx","match":"calix minor","option_only":true},"bijnier":{"title":"Bijnier","short":"Endocriene klier boven de nier die o.a. cortisol, aldosteron en (in het merg) catecholaminen produceert.","definition":"<p>De <b>bijnier</b> (glandula suprarenalis) grenst aan de bovenpool van de nier; links liggen milt, maag en pancreas in de nabijheid.</p>","image_url":"","wiki_title":"Adrenal gland","match":"bijnier","option_only":true},"aneurysma aortae":{"title":"Aneurysma aortae","short":"Blijvende, lokale verwijding van de aorta; op een thoraxfoto zichtbaar als een verbrede aortaschaduw.","definition":"<p>Een <b>aneurysma van de aorta</b> is een pathologische verwijding van de vaatwand. Ruptuur is levensbedreigend.</p>","image_url":"","wiki_title":"Aortic aneurysm","match":"aneurysma aortae","option_only":true},"d-dimeer":{"title":"D-dimeer","short":"Afbraakproduct van fibrine; een normale waarde sluit bij lage verdenking een trombose/longembolie vrijwel uit.","definition":"<p>D-dimeer is een fibrinolyse-afbraakproduct. Een normale waarde bij lage klinische verdenking sluit een longembolie uit; een verhoogde waarde is aspecifiek en vereist beeldvorming.</p>","image_url":"","wiki_title":"","match":"d-dimeer","option_only":true},"malonyl coa":{"title":"Malonyl-CoA","short":"Carboxyleringsproduct van acetyl-CoA dat als bouwsteen dient voor de vetzuursynthese en de vetzuuroxidatie remt.","definition":"<p><b>Malonyl-CoA</b> ontstaat door acetyl-CoA-carboxylase en levert de C2-eenheden voor de groeiende vetzuurketen.</p>","image_url":"","wiki_title":"Malonyl-CoA","match":"malonyl coa","option_only":true},"truncus coeliacus":{"title":"Truncus coeliacus","short":"Eerste onparige tak van de buikaorta die de lever, maag, milt en het bovenste deel van het duodenum van bloed voorziet.","definition":"<p>De <b>truncus coeliacus</b> ontspringt net onder het diafragma uit de aorta abdominalis en splitst zich in de a. gastrica sinistra, a. splenica en a. hepatica communis.</p>","image_url":"","wiki_title":"Celiac artery","match":"truncus coeliacus","option_only":true},"bumetanide":{"title":"Lisdiureticum","short":"Lisdiuretica remmen de NKCC2-cotransporter in de lis van Henle en zijn de krachtigste plasmiddelen.","definition":"<p><strong>Lisdiuretica</strong> zoals furosemide remmen de Na⁺/K⁺/2Cl⁻-cotransporter in het dikke opstijgende deel van de lis van Henle. Ze worden gebruikt bij oedeem door hartfalen, nierziekte of levercirrose en bij longoedeem. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, metabole alkalose, uitdroging en ototoxiciteit; anders dan thiaziden verhogen ze de calciumuitscheiding.</p>","image_url":"","wiki_title":"Loop diuretic","match":"bumetanide","option_only":true},"thiazidediureticum":{"title":"Hydrochloorthiazide","short":"Hydrochloorthiazide is een thiazidediureticum dat de Na⁺/Cl⁻-cotransporter in de distale tubulus remt; eerste keus bij hypertensie.","definition":"<p><strong>Hydrochloorthiazide</strong> remt de <em>Na⁺/Cl⁻-cotransporter</em> (NCC) in de distale convoluut. Daardoor wordt meer natrium en water uitgescheiden; op de lange termijn daalt ook de perifere weerstand.</p><p>Het is een veelgebruikt eerstelijns antihypertensivum. Bijwerkingen: hypokaliëmie, hyponatriëmie, hypomagnesiëmie, hyperurikemie (jicht) en hyperglykemie; de calciumuitscheiding neemt juist af.</p>","image_url":"","wiki_title":"Hydrochlorothiazide","match":"thiazidediureticum","option_only":true},"a.carotis":{"title":"A. carotis communis","short":"De a. carotis communis loopt in de hals omhoog en splitst ter hoogte van het schildkraakbeen in de a. carotis interna en externa.","definition":"<p>Rechts komt de <strong>a. carotis communis</strong> uit de truncus brachiocephalicus, links rechtstreeks uit de aortaboog. Bij de splitsing liggen de sinus caroticus (baroreceptoren) en het glomus caroticum (chemoreceptoren). De carotispols is lateraal van het strottenhoofd voelbaar.</p>","image_url":"","wiki_title":"Common carotid artery","match":"a.carotis","option_only":true},"informatiebias (measurement bias)":{"title":"Informatiebias","short":"Informatiebias is een systematische fout in een onderzoek doordat blootstelling of uitkomst verkeerd wordt gemeten of gerapporteerd.","definition":"<p>Bij <strong>informatiebias</strong> worden deelnemers verkeerd ingedeeld (misclassificatie). Voorbeelden zijn recall bias (patiënten herinneren zich blootstelling beter dan controles), interviewerbias en meetfouten. Als de fout in beide groepen gelijk is (non-differentieel), wordt een verband meestal onderschat; als ze verschilt (differentieel), kan het verband in beide richtingen vertekend raken.</p>","image_url":"","wiki_title":"Information bias (epidemiology)","match":"informatiebias (measurement bias)","option_only":true},"eosinofiele granulocyten":{"title":"Eosinofiele granulocyt","short":"Witte bloedcel met rood-kleurende korrels, actief bij afweer tegen parasieten en bij allergie.","definition":"<p>De <b>eosinofiele granulocyt</b> heeft korrels die met eosine roodroze aankleuren en meestal een tweelobbige kern.</p><p>Hij is betrokken bij de afweer tegen wormparasieten en bij allergische processen zoals astma en eczeem; het aantal is dan vaak verhoogd.</p>","image_url":"","wiki_title":"Eosinophil","match":"eosinofiele granulocyten","option_only":true},"arachidonzuur":{"title":"Arachidonzuur","short":"Vetzuur dat de grondstof vormt voor prostaglandinen (via COX) en leukotriënen (via lipoxygenase).","definition":"<p><b>Arachidonzuur</b> is een meervoudig onverzadigd vetzuur dat als uitgangsstof dient voor twee routes: via <b>COX</b> naar prostaglandinen en via <b>lipoxygenase</b> naar leukotriënen. Remming van de COX-route (door NSAID's) kan de arachidonzuurstroom naar de leukotriënenroute verschuiven.</p>","image_url":"","wiki_title":"Arachidonic acid","match":"arachidonzuur","option_only":true},"prostaglandines":{"title":"Prostaglandines","short":"Lipide-signaalmoleculen die uit arachidonzuur worden gemaakt via cyclo-oxygenase en o.a. ontsteking, pijn en vaattonus reguleren.","definition":"<p><b>Prostaglandines</b> zijn eicosanoïden die uit arachidonzuur ontstaan via COX-enzymen en lokaal werken op vaatwand, bloedstelping en ontstekingsreacties.</p>","image_url":"","wiki_title":"Prostaglandin","match":"prostaglandines","option_only":true},"ductus arteriosus":{"title":"Ductus arteriosus (Botalli)","short":"Foetaal bloedvat tussen longslagader en aorta dat de longcirculatie omzeilt; sluit normaal na de geboorte.","definition":"<p>De <b>ductus arteriosus</b> verbindt in de foetus de a. pulmonalis met de aorta (long → aorta), zodat de longen worden omzeild. Blijft hij open (persisterende ductus arteriosus), dan ontstaat een links-rechtsshunt.</p>","image_url":"","wiki_title":"Ductus arteriosus","match":"ductus arteriosus","option_only":true},"hmg-coa synthase":{"title":"HMG-CoA-synthase","short":"HMG-CoA-synthase maakt HMG-CoA uit acetyl-CoA en acetoacetyl-CoA; een stap in de aanmaak van cholesterol en ketonlichamen.","definition":"<p>In het cytoplasma wordt HMG-CoA door <strong>HMG-CoA-reductase</strong> (het snelheidsbepalende enzym, geremd door statines) omgezet in mevalonaat voor de cholesterolsynthese. In de mitochondriën van de lever wordt HMG-CoA gebruikt om ketonlichamen te maken.</p>","image_url":"","wiki_title":"HMG-CoA synthase","match":"hmg-coa synthase","option_only":true},"squalene monooxygenase":{"title":"Squaleenmonooxygenase","short":"Squaleenmonooxygenase (squaleenepoxidase) is een enzym in de sterolsynthese; bij schimmels wordt het geremd door terbinafine.","definition":"<p>Bij de mens is het een stap in de cholesterolsynthese. Schimmels maken ergosterol; <strong>terbinafine</strong> remt hun squaleenepoxidase en azolen remmen een latere stap (lanosterol-14α-demethylase).</p>","image_url":"","wiki_title":"Squalene monooxygenase","match":"squalene monooxygenase|squaleenepoxidase","option_only":true},"d-dimeer bepalen":{"title":"D-dimeer","short":"D-dimeer is een afbraakproduct van fibrine; een normale waarde maakt trombose of longembolie onwaarschijnlijk bij een laag klinisch risico.","definition":"<p><strong>D-dimeer</strong> is gevoelig maar niet specifiek: het is ook verhoogd na operaties, bij infecties, kanker, zwangerschap en ouderdom. Daarom wordt het alleen gebruikt in combinatie met een beslisregel (Wells, YEARS).</p>","image_url":"","wiki_title":"D-dimer","match":"d-dimeer bepalen|d-dimeer|d-dimeren","option_only":true},"diastolische bloeddruk":{"title":"Bloeddrukwaarden","short":"De diastolische bloeddruk is de laagste druk in de slagaders tijdens de ontspanning van het hart; de gemiddelde arteriële druk (MAP) is de gemiddelde druk over een hele hartcyclus.","definition":"<p>De <strong>MAP</strong> is ongeveer de diastolische druk plus een derde van de polsdruk, en bepaalt de doorbloeding van de organen; op de IC wordt vaak gestreefd naar een MAP van minimaal 65 mmHg.</p>","image_url":"","wiki_title":"Mean arterial pressure","match":"diastolische bloeddruk|gemiddelde bloeddruk|mean arterial pressure|map","option_only":true}};
